module.exports = [{"id":"v-ziyin-cuguang","title":"粗犷","subtitle":"字音 · cū guǎng","grade":"7a","tags":["字音"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"字音"},{"k":"读音","v":"cū guǎng"}]},{"type":"p","text":"粗野，豪放。形容人的性格、举止或艺术风格豪放、不拘小节。"},{"type":"note","title":"易错提示","text":"「犷」读 guǎng，不读 kuàng。声旁虽然写作「广」，却不表示读音，不能见「广」就读成「矿」的音。"},{"type":"quote","text":"他粗犷豪放的歌声在山谷间回荡。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-ziyin-cuguang-q1","type":"choice","stem":"「粗犷」中「犷」的正确读音是（ ）","answer":"A","explain":"「犷」读 guǎng，意为粗野、豪放，如「粗犷」「犷悍」。B 项 kuàng 是「矿、旷、框」的读音，是本题最常见的误读；C 项 guàng 是「逛」的读音；D 项 kuǎng 是「诓、哐」一类的读音，都与「犷」无关。","options":["guǎng","kuàng","guàng","kuǎng"],"difficulty":1,"tags":["字音","形声字","易错音"]},{"id":"v-ziyin-cuguang-q2","type":"fill","stem":"根据拼音写汉字：他性格豪放，歌声粗 guǎng（ ）。","answer":"犷","explain":"「犷」是「犭」（反犬旁）加「广」，本义与兽的凶猛有关，故从「犭」，写作「犷」。写成「旷」（空阔）、「扩」（扩大）都与「粗野豪放」的词义不合。","difficulty":1,"tags":["字形","形近字"]}]},{"id":"v-ziyin-lilin","title":"莅临","subtitle":"字音 · lì lín","grade":"7a","tags":["字音"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"字音"},{"k":"读音","v":"lì lín"}]},{"type":"p","text":"来到，来临。是敬辞，多用于贵宾、上级的到来。"},{"type":"note","title":"易错提示","text":"「莅」读 lì，不读 wèi。因为「莅」与「位」形近，极易误读成「位」的音。"},{"type":"quote","text":"欢迎各位专家莅临我校指导工作。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-ziyin-lilin-q1","type":"choice","stem":"「莅临」中「莅」的正确读音是（ ）","answer":"A","explain":"「莅」读 lì，意为「到」，「莅临」即来到、来临。B 项 wèi 是「位、未」的读音，因「莅」与「位」形近而误读，这是最常见的错误；C 项 lí、D 项 lìn 也都不是「莅」的读音。","options":["lì","wèi","lí","lìn"],"difficulty":1,"tags":["字音","形近字","易错音"]},{"id":"v-ziyin-lilin-q2","type":"fill","stem":"根据拼音写汉字：欢迎各位专家 lì（ ）临我校指导工作。","answer":"莅","explain":"此处应写「莅」，「莅临」是敬辞，表示贵宾或上级到来。不能写成「位临」「利临」「立临」，这些写法既不合词形，也不合敬辞的用法。","difficulty":2,"tags":["字形","敬辞"]}]},{"id":"v-ziyin-yunniang","title":"酝酿","subtitle":"字音 · yùn niàng","grade":"7a","tags":["字音"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"字音"},{"k":"读音","v":"yùn niàng"}]},{"type":"p","text":"本义是造酒时的发酵过程，后比喻做准备工作，也指情绪、气氛等逐渐形成。"},{"type":"note","title":"易错提示","text":"「酝」读 yùn，不读 yūn；「酿」读 niàng，不读 niáng（「娘」的音），也不读 ràng。"},{"type":"quote","text":"春天的气息在湿润的空气里悄悄酝酿。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-ziyin-yunniang-q1","type":"choice","stem":"下列对「酝酿」的注音和解释都正确的一项是（ ）","answer":"A","explain":"「酝酿」读 yùn niàng，本义是造酒的发酵过程，后比喻做准备工作，也可指气氛、情绪逐渐形成。B 项把「酿」误读为 niáng；C 项把「酝」误读为 yūn；D 项把「酿」误读为 ràng，读音全错。","options":["yùn niàng　造酒时的发酵过程，比喻做准备工作","yùn niáng　酿造美酒","yūn niàng　各种气息逐渐形成","yùn ràng　事先商量、准备"],"difficulty":2,"tags":["字音","多音字","词义"]},{"id":"v-ziyin-yunniang-q2","type":"fill","stem":"根据拼音写汉字：这场晚会已经 yùn niàng（ ）了很久。","answer":"酝酿","explain":"「酝」和「酿」都是「酉」旁（与酒有关），本义指造酒的发酵过程，故两个字都不能换成别的偏旁。写作「运酿」「酝量」都是同音或形近致误。","difficulty":2,"tags":["字形","形声字"]}]},{"id":"v-ziyin-gaomiao","title":"高邈","subtitle":"字音 · gāo miǎo","grade":"all","tags":["字音"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"字音"},{"k":"读音","v":"gāo miǎo"}]},{"type":"p","text":"高而远。多形容天空、境界等高远开阔，也可形容思想、情趣超逸。"},{"type":"note","title":"易错提示","text":"「邈」读 miǎo（三声），不读 mào。它和「貌」形近，容易顺口读成「貌」的音。"},{"type":"quote","text":"秋日的天空格外高邈，让人心胸开阔。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-ziyin-gaomiao-q1","type":"choice","stem":"「高邈」中「邈」的正确读音是（ ）","answer":"A","explain":"「邈」读 miǎo，意为遥远，「高邈」即高而远。B 项 mào 是「貌、冒」的读音，因「邈」的右半部分与「貌」相近而误读；C 项 mò、D 项 miáo 都不是「邈」的读音。","options":["miǎo","mào","mò","miáo"],"difficulty":2,"tags":["字音","形近字","易错音"]},{"id":"v-ziyin-gaomiao-q2","type":"fill","stem":"根据拼音写汉字：秋日的天空格外高 miǎo（ ），令人心胸开阔。","answer":"邈","explain":"「邈」是「辶」（走之旁）旁的字，走之旁表示行走、遥远，故「高邈」写作「邈」。规范词形不作「高藐」（「藐」是轻视、小看），也不作「高渺」。","difficulty":2,"tags":["字形","形近字"]}]},{"id":"v-ziyin-duoduobiren","title":"咄咄逼人","subtitle":"字音 · duō duō bī rén","grade":"7a","tags":["字音"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"字音"},{"k":"读音","v":"duō duō bī rén"}]},{"type":"p","text":"形容气势汹汹、盛气凌人，使人难堪；也可形容形势逼人。"},{"type":"note","title":"易错提示","text":"「咄」读 duō（一声），不读 duó。因「咄」与「夺」同声旁而误读为 duó 是最常见的错误。"},{"type":"quote","text":"他说话时总是咄咄逼人，同学们都不敢和他多说。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-ziyin-duoduobiren-q1","type":"choice","stem":"「咄咄逼人」中「咄」的正确读音是（ ）","answer":"A","explain":"「咄」读 duō，本是表示呵叱的叹词，叠用后形容气势逼人。B 项 duó 是「夺、踱」的读音，是本题最易误读的一项；C 项 chū 是「出」的读音；D 项 zhuó 是「拙、浊」的读音。","options":["duō","duó","chū","zhuó"],"difficulty":1,"tags":["字音","形声字","易错音"]},{"id":"v-ziyin-duoduobiren-q2","type":"choice","stem":"下列句子中「咄咄逼人」使用恰当的一项是（ ）","answer":"B","explain":"「咄咄逼人」形容说话气势汹汹、盛气凌人，B 项用来写说话的态度最恰当。A 项写春天的脚步，应改用「悄然而至」一类的词；C 项写雨声大，应用「震耳欲聋」；D 项写色彩鲜艳，应用「鲜艳夺目」，都不能用「咄咄逼人」。","options":["春天的脚步咄咄逼人地来了。","他说话时总是咄咄逼人，同学们都不敢和他交流。","雨越下越大，咄咄逼人的雨声让人睡不着。","这幅画的色彩咄咄逼人，十分鲜艳。"],"difficulty":2,"tags":["成语运用","对象误用"]}]},{"id":"v-ziyin-shenwutongji","title":"深恶痛疾","subtitle":"字音 · shēn wù tòng jí","grade":"8a","tags":["字音"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"字音"},{"k":"读音","v":"shēn wù tòng jí"}]},{"type":"p","text":"厌恶、痛恨到极点。恶：厌恶；痛疾：痛恨。"},{"type":"note","title":"易错提示","text":"「恶」是多音字，在此读 wù（厌恶），不读 è（恶毒），也不读 ě（恶心）。"},{"type":"quote","text":"鲁迅在《藤野先生》中说，他要继续写些为「正人君子」之流所深恶痛疾的文字。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-ziyin-shenwutongji-q1","type":"choice","stem":"「深恶痛疾」中「恶」的正确读音是（ ）","answer":"A","explain":"「恶」作「厌恶、憎恨」讲时读 wù，「深恶痛疾」即厌恶、痛恨到极点。B 项 è 用于「恶毒、恶劣」；C 项 ě 用于「恶心」；D 项 wū 是古汉语中的叹词用法，三者的读音都不合此词。","options":["wù","è","ě","wū"],"difficulty":2,"tags":["字音","多音字","易错音"]},{"id":"v-ziyin-shenwutongji-q2","type":"fill","stem":"「深恶痛疾」的意思是厌恶、痛恨到极点，请写出其中「恶」的意思（ ）。","answer":"厌恶","explain":"「恶」在此是动词，意为厌恶、憎恨；「痛疾」与「痛绝」同义，都表示痛恨到极点。理解这个词的关键是把「恶」读准并讲对，否则容易误解成「恶劣」。","difficulty":2,"tags":["词义","多音字"]}]},{"id":"v-ziyin-xianweirenzhi","title":"鲜为人知","subtitle":"字音 · xiǎn wéi rén zhī","grade":"7b","tags":["字音"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"字音"},{"k":"读音","v":"xiǎn wéi rén zhī"}]},{"type":"p","text":"很少有人知道。鲜：少；为：被。"},{"type":"note","title":"易错提示","text":"「鲜」读 xiǎn（少），不读 xiān（新鲜、鲜明）。"},{"type":"quote","text":"这座古镇鲜为人知，却保存着完整的明清建筑。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-ziyin-xianweirenzhi-q1","type":"choice","stem":"「鲜为人知」中「鲜」的读音和意思是（ ）","answer":"A","explain":"「鲜」读 xiǎn 时意为「少」，「鲜为人知」即很少有人知道，同类用法还有「鲜见」「寡廉鲜耻」。读 xiān 时表示新鲜、味美、鲜明，B、D 两项读音对而释义不合，C 项读音对而释义错。","options":["xiǎn　少","xiān　新鲜","xiǎn　鲜明","xiān　味美"],"difficulty":2,"tags":["字音","多音字","词义"]},{"id":"v-ziyin-xianweirenzhi-q2","type":"fill","stem":"根据拼音写汉字：这座古镇 xiǎn（ ）为人知，却保存着完整的明清建筑。","answer":"鲜","explain":"「鲜为人知」意为很少有人知道，「鲜」在此表「少」，写作「鲜」。不能写成「显为人知」——「显」是显现、显赫，与「少」义无关。","difficulty":2,"tags":["字形","同音字"]}]},{"id":"v-ziyin-ruibukedang","title":"锐不可当","subtitle":"字音 · ruì bù kě dāng","grade":"8a","tags":["字音"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"字音"},{"k":"读音","v":"ruì bù kě dāng"}]},{"type":"p","text":"锋利无比，不可抵挡。形容气势猛烈，来势凶猛。当：抵挡。"},{"type":"note","title":"易错提示","text":"「当」在此读 dāng（抵挡），不读 dàng（恰当、上当）。"},{"type":"quote","text":"毛泽东在《消息二则》中写道：我军锐不可当，迅速突破了敌军防线。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-ziyin-ruibukedang-q1","type":"choice","stem":"「锐不可当」中「当」的正确读音是（ ）","answer":"A","explain":"「当」在此是「抵挡、阻挡」的意思，读 dāng。B 项 dàng 用于「恰当、上当、当铺」；C 项 dǎng 是「挡」的读音，容易与「当」混淆（「势不可挡」写「挡」）；D 项 táng 是「螳、糖」的读音。","options":["dāng","dàng","dǎng","táng"],"difficulty":2,"tags":["字音","多音字","易错音"]},{"id":"v-ziyin-ruibukedang-q2","type":"fill","stem":"「锐不可当」形容来势凶猛、不可抵挡，请写出其中「当」的意思（ ）。","answer":"抵挡","explain":"「当」意为抵挡、阻挡，所以整个成语形容锋利无比、不可抵挡。书写时不要按读音写成「锐不可挡」（规范词形是「锐不可当」），表示「阻挡」义的另有「势不可挡」。","difficulty":2,"tags":["词义","字形"]}]},{"id":"v-ziyin-xiaoshengniji","title":"销声匿迹","subtitle":"字音 · xiāo shēng nì jì","grade":"8b","tags":["字音"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"字音"},{"k":"读音","v":"xiāo shēng nì jì"}]},{"type":"p","text":"不再公开讲话，不再出头露面；形容隐藏起来或不公开出现。匿：隐藏。"},{"type":"note","title":"易错提示","text":"「匿」读 nì，不读 ruò、nuò；「销」是「消失」，不写作「消声匿迹」。"},{"type":"quote","text":"寒冬一到，田野里的昆虫便销声匿迹了。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-ziyin-xiaoshengniji-q1","type":"choice","stem":"「销声匿迹」中「匿」的正确读音是（ ）","answer":"A","explain":"「匿」读 nì，意为隐藏，「销声匿迹」指不再公开露面。B 项 ruò、D 项 nuò 是「若、诺」的读音，与「匿」形音相近，容易混淆；C 项 niè 是「聂、孽」的读音。","options":["nì","ruò","niè","nuò"],"difficulty":2,"tags":["字音","形近字","易错音"]},{"id":"v-ziyin-xiaoshengniji-q2","type":"choice","stem":"下列词语书写完全正确的一项是（ ）","answer":"B","explain":"成语的规范词形是「销声匿迹」：「销」表示消失，「匿」表示隐藏。A 项把「销」写成「消」，属于常见别字；C 项「寄」与「隐藏」义无关；D 项「溺」是淹没、沉溺，都不能构成成语。","options":["消声匿迹","销声匿迹","销声匿寄","消声溺迹"],"difficulty":2,"tags":["字形","成语"]}]},{"id":"v-ziyin-fengxuezaitu","title":"风雪载途","subtitle":"字音 · fēng xuě zài tú","grade":"8b","tags":["字音"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"字音"},{"k":"读音","v":"fēng xuě zài tú"}]},{"type":"p","text":"风雪满路，形容天气恶劣、旅途艰苦。载：充满；途：路途。"},{"type":"note","title":"易错提示","text":"「载」读 zài（充满、装载），不读 zǎi（记载、一年半载）。"},{"type":"quote","text":"即便风雪载途，科考队也没有停下脚步。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-ziyin-fengxuezaitu-q1","type":"choice","stem":"「风雪载途」中「载」的正确读音是（ ）","answer":"A","explain":"「载」读 zài 时表示装载、充满，「风雪载途」即风雪满路。B 项 zǎi 用于「记载、转载、一年半载」；C 项 zāi 不是「载」的读音；D 项 zhài 是「债、寨」的读音。","options":["zài","zǎi","zāi","zhài"],"difficulty":2,"tags":["字音","多音字","易错音"]},{"id":"v-ziyin-fengxuezaitu-q2","type":"fill","stem":"「风雪载途」出自课文《大自然的语言》，形容风雪满路、旅途艰苦。请写出「载」在词中的意思（ ）。","answer":"充满","explain":"「载」在此是「充满」的意思，「载途」即满路，与「怨声载道」中的「载」用法相同。理解了「载」的义项，才能与「记载」的 zǎi 区分开。","difficulty":3,"tags":["词义","多音字"]}]},{"id":"v-ziyin-pianran","title":"翩然","subtitle":"字音 · piān rán","grade":"8b","tags":["字音"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"字音"},{"k":"读音","v":"piān rán"}]},{"type":"p","text":"动作轻快的样子。多形容鸟飞、人舞的样子。"},{"type":"note","title":"易错提示","text":"「翩」读 piān，不读 biǎn；「翩然」强调轻快，不表示「突然」。"},{"type":"quote","text":"燕子翩然归来，春天也就到了。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-ziyin-pianran-q1","type":"choice","stem":"「翩然」中「翩」的正确读音是（ ）","answer":"A","explain":"「翩」读 piān，「翩然」形容动作轻快，课文《大自然的语言》中有「燕子翩然归来」。B 项 biǎn 是「扁、贬」的读音，容易因形近误读；C 项 pián 是「便宜、骈」的读音；D 项 piàn 是「片、骗」的读音。","options":["piān","biǎn","pián","piàn"],"difficulty":1,"tags":["字音","形声字","易错音"]},{"id":"v-ziyin-pianran-q2","type":"fill","stem":"根据拼音写汉字：燕子 piān（ ）然归来，春天也就到了。","answer":"翩","explain":"「翩」是「羽」旁加「扁」，本义与鸟飞有关，故用「羽」旁。写成「偏然」（偏向）、「扁然」都与「动作轻快」的词义不合。","difficulty":2,"tags":["字形","形声字"]}]},{"id":"v-ziyin-junlie","title":"龟裂","subtitle":"字音 · jūn liè","grade":"all","tags":["字音"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"字音"},{"k":"读音","v":"jūn liè"}]},{"type":"p","text":"（皮肤、土地、器物等）裂开许多缝子，呈现出网状裂纹。"},{"type":"note","title":"易错提示","text":"表示「裂开」义时「龟」读 jūn，不读 guī（乌龟）。这是「龟」字最常考的异读。"},{"type":"quote","text":"久旱无雨，田地龟裂，庄稼都蔫了。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-ziyin-junlie-q1","type":"choice","stem":"表示「裂开许多缝子」时，「龟裂」中「龟」的正确读音是（ ）","answer":"A","explain":"「龟」是多音字：读 guī 指乌龟，读 jūn 指皮肤、土地等因干燥而裂开。B 项 guī 是与动物有关的读音，不合此处词义；C 项 qiū、D 项 jiū 都出现在「龟兹」这一古代地名中，与「裂开」义无关。","options":["jūn","guī","qiū","jiū"],"difficulty":2,"tags":["字音","多音字","易错音"]},{"id":"v-ziyin-junlie-q2","type":"fill","stem":"根据拼音写汉字：久旱无雨，田地龟 liè（ ），庄稼都蔫了。","answer":"裂","explain":"「龟裂」指土地、皮肤等裂开许多缝子，后一个字是「裂」，表示裂开。写成「龟列」「龟烈」都是同音致误。","difficulty":1,"tags":["字形","同音字"]}]},{"id":"v-ziyin-guixing","title":"归省","subtitle":"字音 · guī xǐng","grade":"7b","tags":["字音"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"字音"},{"k":"读音","v":"guī xǐng"}]},{"type":"p","text":"回家探望父母、长辈。省：探望、问候。"},{"type":"note","title":"易错提示","text":"「省」在此读 xǐng（探望、反省），不读 shěng（省份、节省）。"},{"type":"quote","text":"照旧时的规矩，出嫁的女儿夏天要归省，回母家住些日子。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-ziyin-guixing-q1","type":"choice","stem":"「归省」中「省」的正确读音是（ ）","answer":"A","explain":"「省」读 xǐng 时有探望、问候、反省等义，「归省」即回家探望父母长辈，课文《社戏》中就有这个词。B 项 shěng 用于「省份、节省」；C 项 xīng、D 项 shèng 都不是「省」的读音。","options":["xǐng","shěng","xīng","shèng"],"difficulty":2,"tags":["字音","多音字","易错音"]},{"id":"v-ziyin-guixing-q2","type":"fill","stem":"根据拼音写汉字：出嫁的女儿照例要回母家 guī xǐng（ ）。","answer":"归省","explain":"「归省」指回家探望父母，「省」读 xǐng 时才有「探望、问候」的意思。不要写作「归醒」或「归幸」，那既不合词形，也与词义无关。","difficulty":2,"tags":["字形","词义"]}]},{"id":"v-ziyin-jiban","title":"羁绊","subtitle":"字音 · jī bàn","grade":"8b","tags":["字音"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"字音"},{"k":"读音","v":"jī bàn"}]},{"type":"p","text":"缠住了不能脱身；束缚。羁：马笼头，引申为束缚。"},{"type":"note","title":"易错提示","text":"「绊」读 bàn，不读 pàn；「羁」读 jī，不读 jì。"},{"type":"quote","text":"他被繁重的家务羁绊，无法远行。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-ziyin-jiban-q1","type":"choice","stem":"「羁绊」中「绊」的正确读音是（ ）","answer":"A","explain":"「绊」读 bàn，意为行走时被东西挡住，「羁绊」即缠住不能脱身。B 项 pàn 是「判、盼」的读音，容易因声旁「半」而误读成 pàn；C 项 bǎn 是「板、版」的读音；D 项 bān 是「搬、班」的读音。","options":["bàn","pàn","bǎn","bān"],"difficulty":2,"tags":["字音","形声字","易错音"]},{"id":"v-ziyin-jiban-q2","type":"fill","stem":"根据拼音写汉字：他被繁重的家务 jī bàn（ ），无法远行。","answer":"羁绊","explain":"「羁」本指马笼头，引申为束缚，字形上是「罒」下加「革」「马」；「绊」是「纟」旁，与绳索有关。写成「机绊」「羁拌」都不合规范词形。","difficulty":3,"tags":["字形","形声字"]}]},{"id":"v-ziyin-kangfen","title":"亢奋","subtitle":"字音 · kàng fèn","grade":"8b","tags":["字音"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"字音"},{"k":"读音","v":"kàng fèn"}]},{"type":"p","text":"极度兴奋。亢：高、极。"},{"type":"note","title":"易错提示","text":"「亢」读 kàng，不读 háng。它和「吭」（读 háng，如「引吭高歌」）形近，极易读错。"},{"type":"quote","text":"鼓声一起，全场观众都亢奋起来。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-ziyin-kangfen-q1","type":"choice","stem":"「亢奋」中「亢」的正确读音是（ ）","answer":"A","explain":"「亢」读 kàng，意为高、极，「亢奋」即极度兴奋，课文《安塞腰鼓》中就用这个词写人的情绪。B 项 háng 是「吭、航」的读音，因「亢」与「吭」形近而误读；C 项 kāng 是「康」的读音；D 项 gāng 是「刚」的读音。","options":["kàng","háng","kāng","gāng"],"difficulty":1,"tags":["字音","形近字","易错音"]},{"id":"v-ziyin-kangfen-q2","type":"fill","stem":"根据拼音写汉字：鼓声一起，全场观众都 kàng（ ）奋起来。","answer":"亢","explain":"「亢奋」意为极度兴奋，用「亢」（高、极）。写成「抗奋」（抵抗）、「伉奋」（伉俪）都不合词义。","difficulty":2,"tags":["字形","同音字"]}]},{"id":"v-ziyin-jilv","title":"羁旅","subtitle":"字音 · jī lǚ","grade":"all","tags":["字音"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"字音"},{"k":"读音","v":"jī lǚ"}]},{"type":"p","text":"作客他乡；客居在外。旅：客居。"},{"type":"note","title":"易错提示","text":"「羁」读 jī，不读 jì；「旅」指客居在外，不能因读音写成「羁履」。"},{"type":"quote","text":"诗人长年羁旅在外，思乡之情溢于言表。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-ziyin-jilv-q1","type":"choice","stem":"「羁旅」中「羁」的正确读音是（ ）","answer":"A","explain":"「羁」读 jī，本义是马笼头，引申为停留、客居，「羁旅」即客居他乡。B 项 jì 是「寄、记」的读音，容易与「羁」的声旁相混；C 项 qí 是「奇、骑」的读音；D 项 gé 是「革」的读音。","options":["jī","jì","qí","gé"],"difficulty":2,"tags":["字音","易错音"]},{"id":"v-ziyin-jilv-q2","type":"fill","stem":"根据拼音写汉字：诗人长年 jī（ ）旅在外，思乡之情溢于言表。","answer":"羁","explain":"「羁旅」指客居他乡，用「羁」（束缚、停留，引申为客居）。写成「机旅」「积旅」都是同音致误。","difficulty":3,"tags":["字形","同音字"]}]},{"id":"v-zixing-cuican","title":"璀璨","subtitle":"字形 · cuǐ càn","grade":"all","tags":["字形"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"字形"},{"k":"读音","v":"cuǐ càn"}]},{"type":"p","text":"形容珠玉等光彩鲜明夺目。"},{"type":"note","title":"易错提示","text":"「璨」是「王（玉）」旁，指美玉的光泽，不能写作「璀璨」以外的「璀灿」；「璀」也是「王」旁。"},{"type":"quote","text":"夜空中繁星璀璨，格外迷人。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-zixing-cuican-q1","type":"choice","stem":"下列词语书写完全正确的一项是（ ）","answer":"A","explain":"「璀璨」二字都是「王（玉）」旁：璀璨本形容珠玉的光泽，故从「玉」。B 项「灿」是「火」旁，用于「灿烂」；C 项「摧」是「扌」旁，意为摧残；D 项「催」是「亻」旁，意为催促，都不能构成该词。","options":["璀璨","璀灿","摧璨","催璨"],"difficulty":2,"tags":["字形","形近字","偏旁"]},{"id":"v-zixing-cuican-q2","type":"fill","stem":"根据拼音写汉字：夜空中繁星 cuǐ càn（ ），格外迷人。","answer":"璀璨","explain":"「璀璨」两个字的偏旁都是「王（玉）」，与珠玉的光彩有关。写作「璀灿」「璀璨」以外的形式如「璀粲」都不合规范词形。","difficulty":2,"tags":["字形","偏旁"]}]},{"id":"v-zixing-changwang","title":"怅惘","subtitle":"字形 · chàng wǎng","grade":"all","tags":["字形"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"字形"},{"k":"读音","v":"chàng wǎng"}]},{"type":"p","text":"惆怅迷惘；心里有事，没精打采。"},{"type":"note","title":"易错提示","text":"「怅」「惘」都是「忄」（竖心旁），表示心理活动，不能写作「怅罔」「帐惘」「伥惘」。"},{"type":"quote","text":"他望着远去的列车，心里一阵怅惘。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-zixing-changwang-q1","type":"choice","stem":"下列词语书写完全正确的一项是（ ）","answer":"A","explain":"「怅」从「忄」，表示惆怅，是内心感受；「惘」也从「忄」，表示迷惘。B 项「罔」是「冂」框，用于「欺罔」；C 项「帐」是「巾」旁，指帐篷、帐目；D 项「伥」是「亻」旁，用于「为虎作伥」，三者都不能构成该词。","options":["怅惘","怅罔","帐惘","伥惘"],"difficulty":2,"tags":["字形","形近字","偏旁"]},{"id":"v-zixing-changwang-q2","type":"fill","stem":"根据拼音写汉字：他望着远去的列车，心里一阵 chàng wǎng（ ）。","answer":"怅惘","explain":"「怅惘」写的是心理状态，两个字都从「忄」（心）：「怅」是惆怅，「惘」是迷惘。写成「帐惘」「怅罔」都是同音或形近致误。","difficulty":3,"tags":["字形","偏旁"]}]},{"id":"v-zixing-tianjing","title":"恬静","subtitle":"字形 · tián jìng","grade":"all","tags":["字形"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"字形"},{"k":"读音","v":"tián jìng"}]},{"type":"p","text":"安静，宁静。多形容环境、生活或人的性格安适平和。"},{"type":"note","title":"易错提示","text":"「恬」是「忄」旁加「舌」，读 tián，不写作「甜静」「括静」。"},{"type":"quote","text":"月光下的小院恬静而美好。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-zixing-tianjing-q1","type":"choice","stem":"下列词语书写完全正确的一项是（ ）","answer":"B","explain":"「恬」从「忄」，表示心境安适，「恬静」即安静、宁静。A 项「甜」指味道甘甜，与「安静」义无关；C 项「括」是「包括」；D 项「净」是干净，都不能与「静」构成规范词形。","options":["甜静","恬静","括静","恬净"],"difficulty":2,"tags":["字形","同音字","偏旁"]},{"id":"v-zixing-tianjing-q2","type":"fill","stem":"「恬静」形容安静、宁静。根据拼音写汉字：tián（ ）静。","answer":"恬","explain":"「恬」是「忄」旁，与人的心境有关，「恬静」形容安适宁静。写作「甜」（味道）或「括」（包括）都属同音、形近致误。","difficulty":2,"tags":["字形","同音字"]}]},{"id":"v-zixing-youhei","title":"黝黑","subtitle":"字形 · yǒu hēi","grade":"8a","tags":["字形"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"字形"},{"k":"读音","v":"yǒu hēi"}]},{"type":"p","text":"黑，黑暗。多形容皮肤、颜色很黑。"},{"type":"note","title":"易错提示","text":"「黝」读 yǒu（三声），右边是「幼」，极易误读成 yòu；字形上是「黑」旁，不写作「有黑」「幼黑」。"},{"type":"quote","text":"他常年在田间劳动，皮肤黝黑。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-zixing-youhei-q1","type":"choice","stem":"「黝黑」中「黝」的正确读音是（ ）","answer":"A","explain":"「黝」读 yǒu（三声），意为黑，「黝黑」形容很黑，课文《列夫·托尔斯泰》中用它写人物的肤色。B 项 yòu 是「幼、右」的读音，因为「黝」右边是「幼」而误读成 yòu，是最常见的错误；C 项 yōu、D 项 yóu 也都不是「黝」的读音。","options":["yǒu","yòu","yōu","yóu"],"difficulty":2,"tags":["字音","形声字","易错音"]},{"id":"v-zixing-youhei-q2","type":"fill","stem":"根据拼音写汉字：他常年在田间劳动，皮肤 yǒu（ ）黑。","answer":"黝","explain":"「黝」是「黑」旁，本身就表示黑色，「黝黑」即很黑。写成「有黑」「幼黑」都是同音致误。","difficulty":2,"tags":["字形","偏旁"]}]},{"id":"v-zixing-cangwunagou","title":"藏污纳垢","subtitle":"字形 · cáng wū nà gòu","grade":"8a","tags":["字形"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"字形"},{"k":"读音","v":"cáng wū nà gòu"}]},{"type":"p","text":"比喻包容、窝藏坏人坏事。垢：污秽、脏东西。"},{"type":"note","title":"易错提示","text":"「垢」是「土」旁，读 gòu，指污秽；不写作「藏污纳诟」「藏污纳后」。"},{"type":"quote","text":"这个混乱的场所藏污纳垢，早就该整治了。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-zixing-cangwunagou-q1","type":"choice","stem":"下列词语书写完全正确的一项是（ ）","answer":"B","explain":"「垢」是「土」旁，本义是污秽、脏东西，读 gòu，与成语中「污」相对，故写作「藏污纳垢」。A 项「诟」是「讠」旁，指辱骂（如「诟骂」）；C 项「后」、D 项「够」都与污秽义无关。","options":["藏污纳诟","藏污纳垢","藏污纳后","藏污纳够"],"difficulty":2,"tags":["字形","偏旁","成语"]},{"id":"v-zixing-cangwunagou-q2","type":"fill","stem":"根据拼音写汉字：这个混乱的场所藏污纳 gòu（ ），早就该整治了。","answer":"垢","explain":"「垢」从「土」，本义是污秽，「藏污纳垢」中「污」与「垢」同义并举。写成「诟」（辱骂）、「后」都是同音或形近致误。","difficulty":3,"tags":["字形","偏旁"]}]},{"id":"v-zixing-jiayuhuxiao","title":"家喻户晓","subtitle":"字形 · jiā yù hù xiǎo","grade":"7b","tags":["字形"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"字形"},{"k":"读音","v":"jiā yù hù xiǎo"}]},{"type":"p","text":"每家每户都知道、都明白，形容人物、事情广为人知。喻：明白；晓：知道。"},{"type":"note","title":"易错提示","text":"「喻」是「口」旁，意为明白、使人知道；不能写作「家谕户晓」（「谕」是上对下的文告）。"},{"type":"quote","text":"邓稼先的名字家喻户晓。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-zixing-jiayuhuxiao-q1","type":"choice","stem":"下列词语书写完全正确的一项是（ ）","answer":"B","explain":"「喻」意为明白、知晓，从「口」；「家喻户晓」即家家户户都明白知道。A 项「谕」指上对下的文告（如「手谕」「面谕」），词义不合；C 项「小」、D 项「宵」与「知晓」义无关。","options":["家谕户晓","家喻户晓","家喻户小","家喻户宵"],"difficulty":2,"tags":["字形","同音字","成语"]},{"id":"v-zixing-jiayuhuxiao-q2","type":"fill","stem":"根据拼音写汉字：他的名字家 yù（ ）户晓。","answer":"喻","explain":"「喻」是「口」旁，本义是告知、使人明白，「家喻户晓」即家家户户都知道。不能写成「谕」——「谕」专指上对下的文告，二者是同音形近字。","difficulty":2,"tags":["字形","同音字"]}]},{"id":"v-zixing-jugongjincui","title":"鞠躬尽瘁","subtitle":"字形 · jū gōng jìn cuì","grade":"7b","tags":["字形"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"字形"},{"k":"读音","v":"jū gōng jìn cuì"}]},{"type":"p","text":"指小心谨慎，贡献出全部精力。瘁：劳累。语出诸葛亮《后出师表》「鞠躬尽力，死而后已」，后世多作「鞠躬尽瘁，死而后已」。"},{"type":"note","title":"易错提示","text":"「瘁」是「疒」（病字旁），意为劳累，不能写作「鞠躬尽粹」（「粹」是纯粹）、「鞠躬尽悴」。"},{"type":"quote","text":"邓稼先为祖国核事业鞠躬尽瘁，死而后已。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-zixing-jugongjincui-q1","type":"choice","stem":"下列词语书写完全正确的一项是（ ）","answer":"B","explain":"「瘁」从「疒」，本义是劳累、病困，「尽瘁」即竭尽劳苦。A 项「粹」是米字旁，意为纯粹；C 项「悴」是「忄」旁，用于「憔悴」（脸色不好）；D 项「萃」是草字头，意为荟萃、聚集，都不能表示劳累。","options":["鞠躬尽粹","鞠躬尽瘁","鞠躬尽悴","鞠躬尽萃"],"difficulty":2,"tags":["字形","形近字","成语"]},{"id":"v-zixing-jugongjincui-q2","type":"fill","stem":"「鞠躬尽瘁，死而后已」中的「瘁」意思是（ ）。","answer":"劳累","explain":"「瘁」意为劳累、竭尽劳苦，所以「尽瘁」是竭尽辛劳，与「憔悴」的「悴」（面色不好）不是同一个字。理解了字义，就不会把「瘁」误写成「粹」「悴」。","difficulty":3,"tags":["字形","词义"]}]},{"id":"v-zixing-yiguzuoqi","title":"一鼓作气","subtitle":"字形 · yī gǔ zuò qì","grade":"9b","tags":["字形"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"字形"},{"k":"读音","v":"yī gǔ zuò qì"}]},{"type":"p","text":"原指作战时擂第一通鼓，士气最盛；后比喻趁劲头大的时候一下子把事情完成。鼓：击鼓。语出《左传·庄公十年》曹刿论战「夫战，勇气也。一鼓作气，再而衰，三而竭」。"},{"type":"note","title":"易错提示","text":"「鼓」是击鼓的意思，不能写作「一股作气」（「股」是量词或指大腿）。"},{"type":"quote","text":"我们一鼓作气，把剩下的活儿干完了。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-zixing-yiguzuoqi-q1","type":"choice","stem":"下列成语书写完全正确的一项是（ ）","answer":"B","explain":"出自《左传·曹刿论战》「一鼓作气，再而衰，三而竭」，「鼓」指击鼓进军，是名词活用为动词。A、D 两项把「鼓」写成「股」，「股」是量词或指大腿，丢掉「击鼓」的本义；C 项「做」也不能表达「振作、兴起」的意思。","options":["一股作气","一鼓作气","一鼓做气","一股做气"],"difficulty":2,"tags":["字形","同音字","成语"]},{"id":"v-zixing-yiguzuoqi-q2","type":"fill","stem":"「一鼓作气」出自《左传·曹刿论战》，请写出其中「鼓」的意思（ ）。","answer":"击鼓","explain":"「鼓」在这里用作动词，意为击鼓（进军）。古代作战以击鼓为进攻信号，第一次击鼓时士气最盛，因此成语才有「趁劲头大时一口气做完」的意思。","difficulty":3,"tags":["词义","词类活用","成语"]}]},{"id":"v-zixing-chuanliubuxi","title":"川流不息","subtitle":"字形 · chuān liú bù xī","grade":"all","tags":["字形"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"字形"},{"k":"读音","v":"chuān liú bù xī"}]},{"type":"p","text":"形容行人、车马等像水流一样连续不断。川：河流；息：停止。"},{"type":"note","title":"易错提示","text":"「川」指河流，不能因「穿过」义写成「穿流不息」。"},{"type":"quote","text":"马路上车水马龙，川流不息。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-zixing-chuanliubuxi-q1","type":"choice","stem":"下列成语书写完全正确的一项是（ ）","answer":"B","explain":"「川」本义是河流，「川流不息」取「像河水一样连续不断」的比喻义。A 项「穿」指穿过、透过，失去了河流的比喻；C 项「留」指停留；D 项「串」指连贯、串联，都不能表达该成语的意思。","options":["穿流不息","川流不息","川留不息","串流不息"],"difficulty":2,"tags":["字形","同音字","成语"]},{"id":"v-zixing-chuanliubuxi-q2","type":"fill","stem":"「川流不息」中的「川」意思是（ ）。","answer":"河流","explain":"「川」的本义是河流，成语用河水奔流不停来比喻人或车马连续不断。这个字义正是判断「川流不息」不能写成「穿流不息」的依据。","difficulty":2,"tags":["词义","成语"]}]},{"id":"v-zixing-pobujidai","title":"迫不及待","subtitle":"字形 · pò bù jí dài","grade":"all","tags":["字形"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"字形"},{"k":"读音","v":"pò bù jí dài"}]},{"type":"p","text":"急迫得不能再等待。及：达到；待：等待。"},{"type":"note","title":"易错提示","text":"「及」是「达到」的意思，不能因同音写作「急」；「迫不急待」是常见的错别字写法。"},{"type":"quote","text":"一拿到新书，他就迫不及待地读了起来。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-zixing-pobujidai-q1","type":"choice","stem":"下列成语书写完全正确的一项是（ ）","answer":"B","explain":"「及」是「达到、赶上」的意思，「迫不及待」即急迫得来不及等待。A、C 两项把「及」写成「急」，是典型的同音致误；D 项「极」也不能与「待」搭配表达「来不及等待」的意思。","options":["迫不急待","迫不及待","迫不急带","迫不极待"],"difficulty":2,"tags":["字形","同音字","成语"]},{"id":"v-zixing-pobujidai-q2","type":"fill","stem":"「迫不及待」中的「及」意思是（ ）。","answer":"达到","explain":"「及」意为达到、赶上，所以「迫不及待」是急迫得来不及等待。明白「及」的义项，就能与「迫不急待」这一错误写法区分开。","difficulty":2,"tags":["词义","成语"]}]},{"id":"v-zixing-zoutouwulu","title":"走投无路","subtitle":"字形 · zǒu tóu wú lù","grade":"all","tags":["字形"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"字形"},{"k":"读音","v":"zǒu tóu wú lù"}]},{"type":"p","text":"无路可走，比喻处境极端困难，找不到出路。投：投奔。"},{"type":"note","title":"易错提示","text":"「投」是投奔的意思，不能因同音写作「走头无路」。"},{"type":"quote","text":"他在绝境中走投无路，只好向朋友求助。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-zixing-zoutouwulu-q1","type":"choice","stem":"下列成语书写完全正确的一项是（ ）","answer":"B","explain":"「投」是投奔、投靠的意思，「走投无路」指无论走向哪里、投奔何处都没有出路。A、D 两项把「投」写成「头」，是同音致误，也丢掉了「投奔」的词义；C 项「陆」与「路」音义都不合。","options":["走头无路","走投无路","走投无陆","走头无陆"],"difficulty":2,"tags":["字形","同音字","成语"]},{"id":"v-zixing-zoutouwulu-q2","type":"fill","stem":"「走投无路」中的「投」意思是（ ）。","answer":"投奔","explain":"「投」意为投奔、投靠，成语的意思是无处可走、无处可投。明白这层意思，就能记住不能写成「走头无路」。","difficulty":2,"tags":["词义","成语"]}]},{"id":"v-zixing-zaijiezaili","title":"再接再厉","subtitle":"字形 · zài jiē zài lì","grade":"all","tags":["字形"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"字形"},{"k":"读音","v":"zài jiē zài lì"}]},{"type":"p","text":"一次又一次地继续努力。厉：磨快，引申为奋勉。语出唐·韩愈、孟郊《斗鸡联句》「一喷一醒然，再接再砺乃」。"},{"type":"note","title":"易错提示","text":"「厉」本作「砺」（磨砺），不能写作「再接再励」；「励」是劝勉、鼓励，与本成语规范词形不同。"},{"type":"quote","text":"老师鼓励我们再接再厉，争取更好的成绩。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-zixing-zaijiezaili-q1","type":"choice","stem":"下列成语书写完全正确的一项是（ ）","answer":"B","explain":"「厉」在这里是「磨快、磨砺」的意思，成语本写斗鸡磨喙再战，比喻一次又一次地努力，规范词形用「厉」。A 项「励」是劝勉、鼓励，属同音致误；C 项「历」是经历；D 项「利」是锋利、利益，都不能表达「磨砺再战」的本义。","options":["再接再励","再接再厉","再接再历","再接再利"],"difficulty":3,"tags":["字形","同音字","成语"]},{"id":"v-zixing-zaijiezaili-q2","type":"fill","stem":"根据拼音写汉字：老师鼓励我们再接再 lì（ ），争取更好的成绩。","answer":"厉","explain":"成语的规范词形是「再接再厉」，「厉」是磨快、磨砺的意思。写作「励」虽然意思接近，但不符合这个成语的固定写法。","difficulty":3,"tags":["字形","成语"]}]},{"id":"v-zixing-mobuguanxin","title":"漠不关心","subtitle":"字形 · mò bù guān xīn","grade":"7a","tags":["字形"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"字形"},{"k":"读音","v":"mò bù guān xīn"}]},{"type":"p","text":"态度冷淡，毫不关心。漠：冷淡。"},{"type":"note","title":"易错提示","text":"「漠」是「氵」旁，意为冷淡；若写成「莫不关心」，意思变成「没有不关心的」，与原意正好相反。"},{"type":"quote","text":"他对集体的事情漠不关心。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-zixing-mobuguanxin-q1","type":"choice","stem":"下列句中词语使用与书写都正确的一项是（ ）","answer":"B","explain":"「漠不关心」指态度冷淡、毫不关心，「漠」是冷淡的意思。「莫」是否定副词，「莫不关心」意为「没有不关心的」，与原意相反，A 项因此错；C、D 两项的「观心」不成词。","options":["他对集体的事情莫不关心。","他对集体的事情漠不关心。","他对集体的事情漠不观心。","他对集体的事情莫不观心。"],"difficulty":2,"tags":["字形","同音字","成语"]},{"id":"v-zixing-mobuguanxin-q2","type":"fill","stem":"根据拼音写汉字：他对集体的事情 mò（ ）不关心。","answer":"漠","explain":"「漠」从「氵」，本指沙漠，引申为冷淡，「漠不关心」即态度冷淡、不关心。写作「莫」会把句意变成「没有不关心的」，与原意相反。","difficulty":2,"tags":["字形","同音字"]}]},{"id":"v-chengyu-bufuzhongwang","title":"不孚众望","subtitle":"成语 · bù fú zhòng wàng","grade":"all","tags":["成语"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"成语"},{"k":"读音","v":"bù fú zhòng wàng"}]},{"type":"p","text":"不能使众人信服。孚：使人信服。含贬义，多指因能力、品行不足而让人失望。"},{"type":"note","title":"易错提示","text":"「孚」读 fú，意为使人信服；本成语与「不负众望」（不辜负大家的期望，含褒义）只差一字，褒贬却完全相反。"},{"type":"quote","text":"新方案不孚众望，遭到了多数人的反对。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-chengyu-bufuzhongwang-q1","type":"choice","stem":"「不孚众望」中「孚」的意思是（ ）","answer":"A","explain":"「孚」是使人信服的意思，「不孚众望」即不能使众人信服，是贬义词。B 项「辜负」对应的是「不负众望」中的「负」；C 项「担负」、D 项「漂浮」与这个词义毫无关系。","options":["使人信服","辜负","担负","漂浮"],"difficulty":2,"tags":["成语","词义","褒贬色彩"]},{"id":"v-chengyu-bufuzhongwang-q2","type":"choice","stem":"下列句子中「不孚众望」使用正确的一项是（ ）","answer":"B","explain":"「不孚众望」是贬义词，指不能使众人信服，B 项「遭到多数人反对」正合此义。A、C、D 三项说的都是「没有辜负大家的期望」，应改用褒义的「不负众望」。","options":["他工作能力出色，不孚众望，当选为班长。","新方案不孚众望，遭到了多数人的反对。","这支球队不孚众望，终于夺得冠军。","他不孚众望，顺利完成了老师交给的任务。"],"difficulty":2,"tags":["成语运用","褒贬色彩","易混成语"]},{"id":"v-chengyu-bufuzhongwang-q3","type":"fill","stem":"请写出与「不孚众望」形近而意思相反、含褒义的成语（ ）。","answer":"不负众望","explain":"「不负众望」的「负」是辜负，整个成语意为不辜负大家的期望，是褒义；「不孚众望」的「孚」是使人信服，意为不能使众人信服，是贬义。一字之差、褒贬相反，是中考高频辨析点。","difficulty":3,"tags":["成语","易混成语","褒贬色彩"]}]},{"id":"v-chengyu-bufuzhongwang2","title":"不负众望","subtitle":"成语 · bù fù zhòng wàng","grade":"all","tags":["成语"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"成语"},{"k":"读音","v":"bù fù zhòng wàng"}]},{"type":"p","text":"不辜负大家的期望。负：辜负。含褒义，用于结果令人满意的语境。"},{"type":"note","title":"易错提示","text":"「负」是辜负，不能写作「服」；不能与贬义的「不孚众望」混用。"},{"type":"quote","text":"女排姑娘不负众望，再次夺得世界冠军。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-chengyu-bufuzhongwang2-q1","type":"choice","stem":"下列句子中「不负众望」使用正确的一项是（ ）","answer":"B","explain":"「不负众望」意为不辜负大家的期望，是褒义词，只能用于结果令人满意的语境，B 项最恰当。A、D 两项说的都是辜负期望，与词义矛盾；C 项是对做法的批评，也不能用褒义词。","options":["他不负众望，最终让大家失望而归。","女排姑娘不负众望，再次夺得世界冠军。","这种敷衍的做法不负众望，引来很多批评。","他辜负了老师的信任，真可谓不负众望。"],"difficulty":2,"tags":["成语运用","褒贬色彩"]},{"id":"v-chengyu-bufuzhongwang2-q2","type":"fill","stem":"「不负众望」中的「负」意思是（ ）。","answer":"辜负","explain":"「负」在这里是辜负的意思，「不负众望」即不辜负大家的期望。与「不孚众望」中的「孚」（使人信服）读音相近而意义相反，要按字义区分。","difficulty":2,"tags":["成语","词义","易混成语"]}]},{"id":"v-chengyu-shoudangqichong","title":"首当其冲","subtitle":"成语 · shǒu dāng qí chōng","grade":"all","tags":["成语"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"成语"},{"k":"读音","v":"shǒu dāng qí chōng"}]},{"type":"p","text":"比喻最先受到攻击或遭遇灾难。冲：要冲，交通要道。语出《汉书·五行志下之上》「郑当其冲，不能修德」。"},{"type":"note","title":"易错提示","text":"常被望文生义地误解为「首先、带头做某事、冲在最前面」，这是最典型的误用。"},{"type":"quote","text":"台风来袭时，沿海的简易房首当其冲，损毁严重。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-chengyu-shoudangqichong-q1","type":"choice","stem":"下列句子中「首当其冲」使用正确的一项是（ ）","answer":"B","explain":"「首当其冲」比喻最先受到攻击或遭遇灾难，B 项「台风中首先受损」正合此义。A、C、D 三项都把成语误解为「走在最前面、带头做某事」，属于望文生义，应改用「一马当先」「率先」等。","options":["运动会入场式上，他首当其冲走在队伍最前面。","台风来袭时，沿海的简易房首当其冲，损毁严重。","讨论会上，他首当其冲发表了自己的意见。","作为班长，他首当其冲承担了打扫教室的任务。"],"difficulty":2,"tags":["成语运用","望文生义"]},{"id":"v-chengyu-shoudangqichong-q2","type":"choice","stem":"关于「首当其冲」，下列说法正确的一项是（ ）","answer":"C","explain":"「首当其冲」出自《汉书·五行志》，「冲」指要冲、交通要道，比喻最先受到冲击或遭遇灾难，多用于不利的处境。A、B 两项把它当成褒义的「带头」，是常见误解；D 项把它理解为单纯的位置靠前，同样不准确。","options":["是褒义词，用来赞美带头做事的人","是褒义词，与「一马当先」意思完全相同","比喻最先受到攻击或遭遇灾难，多用于不好的遭遇","是中性词，只表示位置排在队伍最前面"],"difficulty":2,"tags":["成语","词义","望文生义"]}]},{"id":"v-chengyu-meilunmeihuan","title":"美轮美奂","subtitle":"成语 · měi lún měi huàn","grade":"all","tags":["成语"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"成语"},{"k":"读音","v":"měi lún měi huàn"}]},{"type":"p","text":"形容房屋高大众多、装饰华美。轮：高大；奂：众多。语出《礼记·檀弓下》，张老称赞晋献文子的新居「美哉轮焉，美哉奂焉」。"},{"type":"note","title":"易错提示","text":"使用对象只能是建筑物（房屋、宫殿、馆所），不能形容服饰、舞蹈、歌声、景色等其他事物。"},{"type":"quote","text":"新落成的图书馆美轮美奂，成了校园的标志性建筑。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-chengyu-meilunmeihuan-q1","type":"choice","stem":"下列句子中「美轮美奂」使用正确的一项是（ ）","answer":"C","explain":"「美轮美奂」出自《礼记·檀弓下》，本形容房屋高大众多、装饰华美，使用对象只能是建筑物，C 项正确。A 项形容服饰、B 项形容舞蹈、D 项形容自然景色，都超出了这个成语的使用范围。","options":["她今晚的演出服美轮美奂，格外引人注目。","演员们的舞蹈美轮美奂，赢得阵阵掌声。","新落成的图书馆美轮美奂，成为校园一景。","江南的春色美轮美奂，令人流连忘返。"],"difficulty":2,"tags":["成语运用","对象误用"]},{"id":"v-chengyu-meilunmeihuan-q2","type":"fill","stem":"「美轮美奂」出自《礼记·檀弓下》，请写出其中「轮」的意思（ ）。","answer":"高大","explain":"据郑玄注，「轮」形容房屋高大，「奂」形容众多，所以这个词本是赞叹房屋又高大又多又华美。记住「轮」是高大，「奂」是众多，就能明白它为什么只能形容建筑。","difficulty":3,"tags":["成语","词义","出处"]}]},{"id":"v-chengyu-zhishoukere","title":"炙手可热","subtitle":"成语 · zhì shǒu kě rè","grade":"all","tags":["成语"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"成语"},{"k":"读音","v":"zhì shǒu kě rè"}]},{"type":"p","text":"手一挨近就觉得热，比喻气焰很盛、权势很大。语出唐·杜甫《丽人行》「炙手可热势绝伦，慎莫近前丞相嗔」。含贬义。"},{"type":"note","title":"易错提示","text":"不能用来形容商品畅销、明星走红、话题热门，那样既扩大了对象，也丢掉了贬义。"},{"type":"quote","text":"当时杨国忠一党炙手可热，朝臣敢怒而不敢言。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-chengyu-zhishoukere-q1","type":"choice","stem":"下列句子中「炙手可热」使用正确的一项是（ ）","answer":"C","explain":"「炙手可热」出自杜甫《丽人行》，比喻气焰很盛、权势很大，含贬义，多用于权贵，C 项正确。A 项形容商品畅销应用「供不应求」，B 项形容演员走红应用「红极一时」，D 项形容话题热门应用「备受关注」，三项都属误用。","options":["这款新手机炙手可热，上市当天就被抢购一空。","这位演员凭借一部剧炙手可热，粉丝无数。","当时杨国忠一党炙手可热，朝臣敢怒而不敢言。","「人工智能」是当下炙手可热的话题。"],"difficulty":3,"tags":["成语运用","对象误用","褒贬色彩"]},{"id":"v-chengyu-zhishoukere-q2","type":"fill","stem":"「炙手可热」比喻气焰很盛、权势很大，它含有（ ）色彩（填「褒义」或「贬义」）。","answer":"贬义","explain":"这个成语出自杜甫讽刺杨国忠兄妹骄横的诗句，是贬义词。判断成语能否使用，除了看对象，还要看感情色彩，用它去赞美正当走红的人或畅销的商品就容易出错。","difficulty":2,"tags":["成语","褒贬色彩"]}]},{"id":"v-chengyu-chaqiangrenyi","title":"差强人意","subtitle":"成语 · chā qiáng rén yì","grade":"all","tags":["成语"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"成语"},{"k":"读音","v":"chā qiáng rén yì"}]},{"type":"p","text":"大体上还能使人满意。差：稍微、大致；强：振奋。语出《后汉书·吴汉传》「帝……乃叹曰：吴公差强人意」。"},{"type":"note","title":"易错提示","text":"常被误解为「不能使人满意」，意思正好说反；它其实是一个偏褒的评价。"},{"type":"quote","text":"这篇作文虽不算出色，但还算差强人意。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-chengyu-chaqiangrenyi-q1","type":"choice","stem":"下列句子中「差强人意」使用正确的一项是（ ）","answer":"B","explain":"「差强人意」出自《后汉书·吴汉传》，「差」是稍微、大致，「强」是振奋，整个成语意为大体上还能使人满意，是偏褒的评价，B 项正确。A、C、D 三项说的都是令人失望、要投诉，与原意正好相反。","options":["这次考试成绩差强人意，他很失望。","这篇作文虽不出色，但还算差强人意。","餐厅的菜又贵又难吃，真是差强人意。","服务态度差强人意，顾客纷纷投诉。"],"difficulty":3,"tags":["成语运用","望文生义","词义"]},{"id":"v-chengyu-chaqiangrenyi-q2","type":"fill","stem":"「差强人意」中的「差」意思是（ ）。","answer":"稍微","explain":"「差」读 chā，是稍微、大致的意思，「差强人意」即大致还能振奋人心、大体上令人满意。「差」不能理解成「差劲」「不好」，否则就会把整个成语的意思弄反。","difficulty":3,"tags":["成语","词义","多音字"]}]},{"id":"v-chengyu-qiaoduotiangong","title":"巧夺天工","subtitle":"成语 · qiǎo duó tiān gōng","grade":"all","tags":["成语"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"成语"},{"k":"读音","v":"qiǎo duó tiān gōng"}]},{"type":"p","text":"人工的精巧胜过天然，形容技艺极其精巧。夺：胜过。语出元·赵孟頫《赠放烟火者》「人间巧艺夺天工」。"},{"type":"note","title":"易错提示","text":"只能形容人工制作的物品和人的技艺，不能形容天然形成的山水、奇石、雪花。"},{"type":"quote","text":"这件牙雕作品巧夺天工，观众赞不绝口。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-chengyu-qiaoduotiangong-q1","type":"choice","stem":"下列句子中「巧夺天工」使用正确的一项是（ ）","answer":"B","explain":"「巧夺天工」意为人工的精巧胜过天然，因此只能形容人的技艺和人工制品，B 项正确。A、C、D 三项描写的桂林山水、黄山奇石、雪花都是天然形成的，无所谓「人工胜过天然」，使用对象不当。","options":["桂林山水巧夺天工，令人流连忘返。","这件牙雕作品巧夺天工，观众赞不绝口。","黄山的奇石巧夺天工，形态各异。","雪花漫天飞舞，巧夺天工。"],"difficulty":2,"tags":["成语运用","对象误用"]},{"id":"v-chengyu-qiaoduotiangong-q2","type":"fill","stem":"「巧夺天工」中的「夺」意思是（ ）。","answer":"胜过","explain":"「夺」在这里是胜过、超过的意思，「巧夺天工」即人工的巧妙胜过天然。把这个字的意思讲准，就能明白它不能用来形容天然景物本身。","difficulty":3,"tags":["成语","词义"]}]},{"id":"v-chengyu-weimiaoweixiao","title":"惟妙惟肖","subtitle":"成语 · wéi miào wéi xiào","grade":"all","tags":["成语"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"成语"},{"k":"读音","v":"wéi miào wéi xiào"}]},{"type":"p","text":"形容描写或模仿得非常好，非常逼真。肖：相似。"},{"type":"note","title":"易错提示","text":"「肖」读 xiào，不读 xiāo；只能形容人的描写、模仿、表演、绘画等，不能形容天然景物本身。"},{"type":"quote","text":"他模仿各地方言惟妙惟肖，令人捧腹。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-chengyu-weimiaoweixiao-q1","type":"choice","stem":"「惟妙惟肖」中「肖」的正确读音是（ ）","answer":"A","explain":"「肖」表示相似时读 xiào，如「惟妙惟肖」「肖像」。B 项 xiāo 是姓氏「肖」的读音；C 项 xiǎo、D 项 qiào 都不是「相似」这一义项的读音。","options":["xiào","xiāo","xiǎo","qiào"],"difficulty":2,"tags":["字音","多音字","成语"]},{"id":"v-chengyu-weimiaoweixiao-q2","type":"choice","stem":"下列句子中「惟妙惟肖」使用正确的一项是（ ）","answer":"B","explain":"「惟妙惟肖」形容描写或模仿得非常逼真，对象是人的模仿、表演、绘画等，B 项正确。A 项山峰是天然形成的，不存在「模仿得像」；C 项评价书法独创风格应用「自成一家」，与「逼真」无关；D 项只说色彩明丽，与「肖」（相像）无关。","options":["张家界的山峰惟妙惟肖，像一个个巨人。","他模仿各地方言惟妙惟肖，令人捧腹。","他的书法惟妙惟肖，自成一家。","这幅画色彩明丽，可谓惟妙惟肖。"],"difficulty":2,"tags":["成语运用","对象误用"]}]},{"id":"v-chengyu-lincizhibi","title":"鳞次栉比","subtitle":"成语 · lín cì zhì bǐ","grade":"all","tags":["成语"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"成语"},{"k":"读音","v":"lín cì zhì bǐ"}]},{"type":"p","text":"像鱼鳞和梳子的齿那样密密地排列着，多形容房屋、船只等排列密集整齐。栉：梳子、篦子。语本《诗经·周颂·良耜》「其比如栉」。"},{"type":"note","title":"易错提示","text":"「栉」读 zhì，不读 jié；只能形容建筑、船只等排列密集，不能形容人数多或树木杂乱。"},{"type":"quote","text":"江边的楼房鳞次栉比，一眼望不到头。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-chengyu-lincizhibi-q1","type":"choice","stem":"「鳞次栉比」中「栉」的正确读音是（ ）","answer":"A","explain":"「栉」读 zhì，本义是梳子、篦子，「栉比」即像梳齿那样密密排列。B 项 jié 是「节、结」的读音，容易因形近误读；C 项 zì、D 项 zhǐ 也都不是「栉」的读音。","options":["zhì","jié","zì","zhǐ"],"difficulty":3,"tags":["字音","形近字","成语"]},{"id":"v-chengyu-lincizhibi-q2","type":"fill","stem":"「鳞次栉比」中的「栉」指（ ）。","answer":"梳子","explain":"「栉」指梳子、篦子，梳齿排列细密整齐，成语正是用这个特点来比喻房屋、船只等排列密集。理解这个字义，就能明白成语为什么不用于形容人。","difficulty":3,"tags":["成语","词义"]}]},{"id":"v-chengyu-xiangdeyizhang","title":"相得益彰","subtitle":"成语 · xiāng dé yì zhāng","grade":"all","tags":["成语"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"成语"},{"k":"读音","v":"xiāng dé yì zhāng"}]},{"type":"p","text":"互相帮助、互相补充，更能显出各自的好处。彰：明显。语本《史记·伯夷列传》「伯夷、叔齐虽贤，得夫子而名益彰」。含褒义。"},{"type":"note","title":"易错提示","text":"强调双方互相配合、互相衬托，主语通常是两个方面；含褒义，不能用于坏事或缺点相加。"},{"type":"quote","text":"青砖灰瓦与绿树相得益彰，小院格外雅致。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-chengyu-xiangdeyizhang-q1","type":"choice","stem":"下列句子中「相得益彰」使用正确的一项是（ ）","answer":"B","explain":"「相得益彰」指互相配合、互相补充，更能显出各自的好处，是褒义词，B 项中景与物互相映衬，使用恰当。A 项只是并列两个优点，没有「互相配合」的意思；C 项褒词贬用；D 项把缺点叠加说成「相得益彰」，语义和色彩都错。","options":["他的书法和绘画都很出色，真是相得益彰。","青砖灰瓦与绿树相得益彰，小院格外雅致。","这两个骗子互相配合，可谓相得益彰。","他又懒惰又粗心，两个缺点相得益彰。"],"difficulty":3,"tags":["成语运用","褒贬色彩"]},{"id":"v-chengyu-xiangdeyizhang-q2","type":"fill","stem":"「相得益彰」中的「彰」意思是（ ）。","answer":"明显","explain":"「彰」是明显、显著的意思，「相得益彰」即互相配合而各自的长处更加显著。抓住「彰」的字义，就能明白这个成语必须有「双方对照」的语境。","difficulty":3,"tags":["成语","词义"]}]},{"id":"v-chengyu-tanweiguanzhi","title":"叹为观止","subtitle":"成语 · tàn wéi guān zhǐ","grade":"all","tags":["成语"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"成语"},{"k":"读音","v":"tàn wéi guān zhǐ"}]},{"type":"p","text":"赞美所见到的事物好到了极点。语出《左传·襄公二十九年》，吴国季札观周乐，赞叹「观止矣」。含褒义。"},{"type":"note","title":"易错提示","text":"只用于赞叹极好的事物，不能用于灾难、丑恶现象或别人的缺点；「为」读 wéi。"},{"type":"quote","text":"这套杂技动作惊险优美，观众叹为观止。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-chengyu-tanweiguanzhi-q1","type":"choice","stem":"下列句子中「叹为观止」使用正确的一项是（ ）","answer":"B","explain":"「叹为观止」出自《左传·襄公二十九年》季札观乐「观止矣」，意为赞叹所见事物好到极点，是褒义词，B 项用它赞美精彩表演，使用恰当。A 项是灾难场面、C 项是缺点、D 项是恶劣现象，都不能用褒义的赞叹之词。","options":["那场火灾的场面令人叹为观止。","这套杂技动作惊险优美，观众叹为观止。","他的粗心大意让人叹为观止。","这里垃圾堆积如山，让人叹为观止。"],"difficulty":2,"tags":["成语运用","褒贬色彩"]},{"id":"v-chengyu-tanweiguanzhi-q2","type":"choice","stem":"「叹为观止」这一成语出自（ ）","answer":"A","explain":"《左传·襄公二十九年》记载吴国公子季札到鲁国观周乐，看到《韶箾》时赞叹「观止矣！若有他乐，吾不敢请已」，成语「叹为观止」由此而来。B 项《史记》是司马迁的纪传体史书，C、D 两项是儒家经典，都不是这个成语的出处。","options":["《左传》","《史记》","《论语》","《孟子》"],"difficulty":3,"tags":["成语","出处","文学常识"]}]},{"id":"v-chengyu-bieju-jiangxin","title":"别具匠心","subtitle":"成语 · bié jù jiàng xīn","grade":"all","tags":["成语"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"成语"},{"k":"读音","v":"bié jù jiàng xīn"}]},{"type":"p","text":"另有一种巧妙的心思，多指文学、艺术方面创造性的构思。匠心：巧妙的心思。含褒义。"},{"type":"note","title":"易错提示","text":"与「别具一格」（另有一种独特的风格）不同：前者强调构思巧妙，后者强调风格独特；含褒义，不能用来贬斥别人。"},{"type":"quote","text":"这篇小说的结构别具匠心，读来引人入胜。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-chengyu-bieju-jiangxin-q1","type":"choice","stem":"「别具匠心」的意思是（ ）","answer":"B","explain":"「匠心」指巧妙的心思，「别具匠心」强调构思、设计巧妙，多用于文学艺术创作，是褒义词。A 项是「别具一格」的意思，强调风格独特；C、D 两项把这个褒义词误解成贬义，都不正确。","options":["另有一种独特的风格","另有一种巧妙的心思，多指文艺创作的构思","和别人格格不入，处不到一起","心思过于独特，不合常理"],"difficulty":2,"tags":["成语","词义","易混成语"]},{"id":"v-chengyu-bieju-jiangxin-q2","type":"fill","stem":"「别具匠心」中的「匠心」意思是（ ）。","answer":"巧妙的心思","explain":"「匠心」指巧妙的心思、独特的构思，所以「别具匠心」形容文艺创作有独到的巧妙设计。理解「匠心」是解读这类成语的关键，如「独具匠心」用法相同。","difficulty":2,"tags":["成语","词义"]}]},{"id":"v-chengyu-yiyangduncuo","title":"抑扬顿挫","subtitle":"成语 · yì yáng dùn cuò","grade":"all","tags":["成语"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"成语"},{"k":"读音","v":"yì yáng dùn cuò"}]},{"type":"p","text":"声音高低起伏和停顿转折，形容声音和谐悦耳。多用于朗读、朗诵、音乐和说话。"},{"type":"note","title":"易错提示","text":"只用来形容声音，不能形容情节曲折、舞蹈动作或线条变化。"},{"type":"quote","text":"他的朗诵抑扬顿挫，十分动听。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-chengyu-yiyangduncuo-q1","type":"choice","stem":"下列句子中「抑扬顿挫」使用正确的一项是（ ）","answer":"B","explain":"「抑扬顿挫」形容声音的高低起伏和停顿转折，使用对象是声音（朗读、音乐、说话），B 项正确。A 项形容情节应说「跌宕起伏」，C 项形容动作应说「舒展流畅」，D 项线条变化更与声音无关，三项都是对象误用。","options":["这篇小说的情节抑扬顿挫，引人入胜。","他的朗诵抑扬顿挫，赢得阵阵掌声。","舞者的动作抑扬顿挫，富有韵律。","这幅画的线条抑扬顿挫，很有张力。"],"difficulty":2,"tags":["成语运用","对象误用"]},{"id":"v-chengyu-yiyangduncuo-q2","type":"fill","stem":"「抑扬顿挫」形容的是（ ）方面的特点（填「声音」或「情节」等词语）。","answer":"声音","explain":"「抑扬」指声音高低起伏，「顿挫」指停顿转折，整个成语形容声音和谐悦耳，因此其使用对象只能是声音。判断这类成语能否使用，关键看它描写的对象是否与词义一致。","difficulty":2,"tags":["成语","对象误用"]}]},{"id":"v-chengyu-qinggemanwu","title":"轻歌曼舞","subtitle":"成语 · qīng gē màn wǔ","grade":"all","tags":["成语"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"成语"},{"k":"读音","v":"qīng gē màn wǔ"}]},{"type":"p","text":"轻松愉快的歌声和柔和优美的舞蹈。曼：柔美。"},{"type":"note","title":"易错提示","text":"「曼」不能写作「漫」；也不用于形容节奏强烈的劲歌热舞。"},{"type":"quote","text":"舞台上轻歌曼舞，观众如痴如醉。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-chengyu-qinggemanwu-q1","type":"choice","stem":"下列词语书写完全正确的一项是（ ）","answer":"B","explain":"「曼」意为柔美、轻柔，「轻歌曼舞」指轻松的歌声和柔美的舞蹈。A 项「漫」是水漫溢、散漫；C 项「清」虽可形容歌声清亮，但规范词形用「轻」；D 项「慢」表示速度慢，与「柔美」义不合。","options":["轻歌漫舞","轻歌曼舞","清歌曼舞","轻歌慢舞"],"difficulty":3,"tags":["字形","同音字","成语"]},{"id":"v-chengyu-qinggemanwu-q2","type":"fill","stem":"「轻歌曼舞」中的「曼」意思是（ ）。","answer":"柔美","explain":"「曼」是柔美、轻柔的意思，所以「轻歌曼舞」写的是轻松的歌声和柔美的舞姿。明白字义就能记住不能写成「漫」（水漫、散漫）或「慢」（速度慢）。","difficulty":3,"tags":["成语","词义"]}]},{"id":"v-chengyu-jiaranerzhi","title":"戛然而止","subtitle":"成语 · jiá rán ér zhǐ","grade":"all","tags":["成语"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"成语"},{"k":"读音","v":"jiá rán ér zhǐ"}]},{"type":"p","text":"形容声音突然中止。戛：拟声词，形容声音突然中止。语出清·李绿园《歧路灯》「忽得锣鼓戛然而止」。"},{"type":"note","title":"易错提示","text":"「戛」读 jiá，不读 gā；只形容声音突然停止，不能形容动作、事件突然结束。"},{"type":"quote","text":"琴声戛然而止，屋里一片寂静。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-chengyu-jiaranerzhi-q1","type":"choice","stem":"「戛然而止」中「戛」的正确读音是（ ）","answer":"A","explain":"「戛」读 jiá，是形容声音的拟声词，「戛然而止」指声音突然中止。B 项 gā 是「嘎」的读音，虽有「嘎然而止」的写法，但规范词形是「戛然而止」；C 项 jiā、D 项 xiá 都不是「戛」的读音。","options":["jiá","gā","jiā","xiá"],"difficulty":2,"tags":["字音","形近字","成语"]},{"id":"v-chengyu-jiaranerzhi-q2","type":"fill","stem":"「戛然而止」形容的对象是（ ）（填「声音」「动作」等词语）。","answer":"声音","explain":"「戛然」是形容声音突然停止的拟声词，所以这个成语只能用于声音（琴声、锣鼓声、说话声等）突然中止，不能用来写动作或事件的中断。","difficulty":2,"tags":["成语","对象误用"]}]},{"id":"v-chengyu-dachedawu","title":"大彻大悟","subtitle":"成语 · dà chè dà wù","grade":"all","tags":["成语"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"成语"},{"k":"读音","v":"dà chè dà wù"}]},{"type":"p","text":"形容彻底觉悟或醒悟。彻：透彻。原为佛教用语，指彻底觉悟。"},{"type":"note","title":"易错提示","text":"语意很重，指认识上的根本转变，不能形容小事的「明白了」；也不能写作「大彻大误」。"},{"type":"quote","text":"经历这场大病，他大彻大悟，从此不再计较得失。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-chengyu-dachedawu-q1","type":"choice","stem":"下列句子中「大彻大悟」使用正确的一项是（ ）","answer":"B","explain":"「大彻大悟」原为佛教用语，指彻底觉悟，语意很重，适合认识发生根本转变的语境，B 项正确。A 项只是听懂一道题，程度过重，应用「恍然大悟」；C 项语法搭配不当，「大彻大悟」不能作状语修饰「写完作业」；D 项与「觉悟」毫无关系。","options":["听老师讲完这道题，我大彻大悟。","经历这场大病，他大彻大悟，从此不再计较得失。","他大彻大悟地写完了作业。","这道菜的味道让我大彻大悟。"],"difficulty":3,"tags":["成语运用","程度失当"]},{"id":"v-chengyu-dachedawu-q2","type":"fill","stem":"根据拼音写汉字：经历这场大病，他大 chè（ ）大悟，从此不再计较得失。","answer":"彻","explain":"「彻」是透彻、彻底的意思，「大彻大悟」即彻底觉悟。写作「大澈大悟」是形近致误，「澈」是水清，与「彻底明白」义不同。","difficulty":3,"tags":["字形","形近字","成语"]}]},{"id":"v-chengyu-renqingshigu","title":"人情世故","subtitle":"成语 · rén qíng shì gù","grade":"all","tags":["成语"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"成语"},{"k":"读音","v":"rén qíng shì gù"}]},{"type":"p","text":"为人处世的道理。世故：处世经验。"},{"type":"note","title":"易错提示","text":"「世故」不能写作「事故」（「事故」指意外的灾祸）；「老于世故」含贬义，本词本身是中性词。"},{"type":"quote","text":"他年纪不大，却很懂人情世故。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-chengyu-renqingshigu-q1","type":"choice","stem":"下列词语书写完全正确的一项是（ ）","answer":"B","explain":"「世故」指处世经验、人情变故，与「为人处世的道理」相关，故写作「人情世故」。A 项「事故」指意外的损失或灾祸（如交通事故），是最常见的别字；C 项「固」、D 项「清」都不能构成该词。","options":["人情事故","人情世故","人情世固","人清世故"],"difficulty":2,"tags":["字形","同音字","成语"]},{"id":"v-chengyu-renqingshigu-q2","type":"fill","stem":"根据拼音写汉字：他年纪不大，却很懂人情 shì（ ）故。","answer":"世","explain":"「世故」指处世经验、待人接物的道理，用「世」。写作「事故」就把意思变成了「意外灾祸」，与「懂道理」正好相悖。","difficulty":2,"tags":["字形","同音字"]}]},{"id":"v-chengyu-zichuxincai","title":"自出心裁","subtitle":"成语 · zì chū xīn cái","grade":"all","tags":["成语"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"成语"},{"k":"读音","v":"zì chū xīn cái"}]},{"type":"p","text":"出于自己心中的设计或筹划，指独创一格、与众不同。心裁：心中的设计、构思。"},{"type":"note","title":"易错提示","text":"「裁」是裁剪、构思，不能写作「自出心栽」「自出心载」。"},{"type":"quote","text":"这件手工作品自出心裁，评委赞不绝口。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-chengyu-zichuxincai-q1","type":"choice","stem":"下列词语书写完全正确的一项是（ ）","answer":"B","explain":"「裁」本义是裁剪衣服，引申为构思、安排，「心裁」即心中的设计，故写作「自出心裁」。A 项「栽」是栽种；C 项「载」是装载；D 项「新」与「心」同音，都不能替换成语中的固定用字。","options":["自出心栽","自出心裁","自出心载","自出新裁"],"difficulty":3,"tags":["字形","同音字","成语"]},{"id":"v-chengyu-zichuxincai-q2","type":"choice","stem":"与「自出心裁」意思最接近的成语是（ ）","answer":"A","explain":"「自出心裁」指出于自己的构思、独创一格，与「别出心裁」意思最接近。B 项「循规蹈矩」是遵守规矩、不敢变动，C 项「亦步亦趋」是处处模仿别人，都与「独创」的意思相反；D 项「大相径庭」是彼此相差很远，与「独创」无关。","options":["别出心裁","循规蹈矩","亦步亦趋","大相径庭"],"difficulty":2,"tags":["成语","近义成语"]}]},{"id":"v-ciyu-zhuxu","title":"贮蓄","subtitle":"词语 · zhù xù","grade":"7a","tags":["词语"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"词语"},{"k":"读音","v":"zhù xù"}]},{"type":"p","text":"储存，积蓄。多指把财物或某种东西存放、蓄积起来。"},{"type":"note","title":"易错提示","text":"课文中写作「贮蓄」，「贮」是「贝」旁（与财物有关）；写作「贮畜」「伫蓄」都不合词形。"},{"type":"quote","text":"水藻真绿，把终年贮蓄的绿色全拿出来了。（《济南的冬天》）","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-ciyu-zhuxu-q1","type":"choice","stem":"下列词语书写完全正确的一项是（ ）","answer":"A","explain":"「贮」是「贝」旁，本义是积存财物，与「蓄」（积聚）组合成「贮蓄」，课文《济南的冬天》中就用这个词。B 项「畜」指家畜；C 项「伫」是久立（伫立）；D 项「绪」是头绪，都不能构成该词。","options":["贮蓄","贮畜","伫蓄","贮绪"],"difficulty":2,"tags":["字形","形近字","课内词语"]},{"id":"v-ciyu-zhuxu-q2","type":"fill","stem":"《济南的冬天》中写道「把终年 zhù xù（ ）的绿色全拿出来了」，请写出这个词。","answer":"贮蓄","explain":"「贮蓄」意为储存、积蓄，课文用它写水藻蓄积了一年的绿色。「贮」从「贝」，表示存放；写成「储」虽意思相近，但课文的规范词形是「贮蓄」。","difficulty":2,"tags":["字形","课内词语"]}]},{"id":"v-ciyu-jingmi","title":"静谧","subtitle":"词语 · jìng mì","grade":"7a","tags":["词语"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"词语"},{"k":"读音","v":"jìng mì"}]},{"type":"p","text":"安静，寂静。多形容环境安宁无声。"},{"type":"note","title":"易错提示","text":"「谧」读 mì，是「讠」旁，声旁为「必」，容易误读成 bì；也不能写作「静密」「静泌」。"},{"type":"quote","text":"深夜的校园一片静谧。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-ciyu-jingmi-q1","type":"choice","stem":"「静谧」中「谧」的正确读音是（ ）","answer":"A","explain":"「谧」读 mì，意为安宁，「静谧」即安静。B 项 bì 是「必、秘」的读音，因「谧」的声旁是「必」而误读成 bì，这是最常见的错误；C 项 nì、D 项 mǐ 也都不是「谧」的读音。","options":["mì","bì","nì","mǐ"],"difficulty":2,"tags":["字音","形声字","易错音"]},{"id":"v-ciyu-jingmi-q2","type":"fill","stem":"根据拼音写汉字：深夜的校园一片静 mì（ ）。","answer":"谧","explain":"「谧」是「讠」旁加「必」，本义是安宁、平静，故「静谧」写作「谧」。写成「静密」（稠密）、「静泌」（分泌）都与「安宁」的词义不合。","difficulty":2,"tags":["字形","同音字"]}]},{"id":"v-ciyu-linse","title":"吝啬","subtitle":"词语 · lìn sè","grade":"7a","tags":["词语"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"词语"},{"k":"读音","v":"lìn sè"}]},{"type":"p","text":"过分爱惜自己的财物，当用不用。"},{"type":"note","title":"易错提示","text":"「啬」读 sè，不读 qiáng（易与「墙、蔷」的右旁相混）；不写作「吝色」「吝穑」。"},{"type":"quote","text":"他并不吝啬，常常资助贫困学生。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-ciyu-linse-q1","type":"choice","stem":"「吝啬」中「啬」的正确读音是（ ）","answer":"A","explain":"「啬」读 sè，「吝啬」指过分爱惜财物、当用不用。B 项 qiáng 是「墙、蔷」的读音，因「啬」与「墙」的右半部分相混而误读；C 项 shè、D 项 sài 也都不是「啬」的读音。","options":["sè","qiáng","shè","sài"],"difficulty":3,"tags":["字音","形近字","易错音"]},{"id":"v-ciyu-linse-q2","type":"fill","stem":"根据拼音写汉字：他并不 lìn sè（ ），常常资助贫困学生。","answer":"吝啬","explain":"「吝啬」指过分爱惜财物、该用不用，二字都从「口」或在字形上与「口」有关，写作「吝色」「吝穑」都不合规范词形。","difficulty":3,"tags":["字形","课内词语"]}]},{"id":"v-ciyu-jianmo","title":"缄默","subtitle":"词语 · jiān mò","grade":"8b","tags":["词语"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"词语"},{"k":"读音","v":"jiān mò"}]},{"type":"p","text":"闭口不说话。缄：封闭。"},{"type":"note","title":"易错提示","text":"「缄」读 jiān，是「纟」旁，容易与「箴」（zhēn，箴言）混淆；不能写作「减默」。"},{"type":"quote","text":"面对众人的追问，他始终保持缄默。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-ciyu-jianmo-q1","type":"choice","stem":"「缄默」中「缄」的正确读音是（ ）","answer":"A","explain":"「缄」读 jiān，本义是捆东西的绳索，引申为封闭，「缄默」即闭口不言。B 项 jiǎn 是「减、检」的读音；C 项 xián 是「咸、衔」的读音；D 项 zhēn 是「箴、针」的读音，因「箴」与「缄」形近而误读。","options":["jiān","jiǎn","xián","zhēn"],"difficulty":3,"tags":["字音","形近字","易错音"]},{"id":"v-ciyu-jianmo-q2","type":"fill","stem":"根据拼音写汉字：面对众人的追问，他始终保持 jiān（ ）默。","answer":"缄","explain":"「缄」是「纟」旁，本义是捆扎、封口，「缄默」即闭口不说话。写成「箴默」「减默」都不合规范词形。","difficulty":3,"tags":["字形","形近字"]}]},{"id":"v-ciyu-cuanduo","title":"撺掇","subtitle":"词语 · cuān duo","grade":"7b","tags":["词语"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"词语"},{"k":"读音","v":"cuān duo"}]},{"type":"p","text":"从旁鼓动人做某事；怂恿。"},{"type":"note","title":"易错提示","text":"「撺」读 cuān（一声），不读 cuàn；「掇」在这里读轻声 duo，不读 duó。"},{"type":"quote","text":"几个朋友撺掇他去参加这次比赛。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-ciyu-cuanduo-q1","type":"choice","stem":"「撺掇」中「撺」的正确读音是（ ）","answer":"A","explain":"「撺」读 cuān（一声），是「扌」旁，本义是抛掷，引申为怂恿、鼓动。B 项 cuàn 是「窜、篡」的读音，容易误读；C 项 chuān 是「川、穿」的读音；D 项 zhuān 是「专、砖」的读音。","options":["cuān","cuàn","chuān","zhuān"],"difficulty":3,"tags":["字音","形近字","易错音"]},{"id":"v-ciyu-cuanduo-q2","type":"fill","stem":"根据拼音写汉字：几个朋友 cuān duo（ ）他去参加这次比赛。","answer":"撺掇","explain":"「撺掇」指从旁鼓动别人做某事，两个字都是「扌」旁，与手的动作有关，课文《社戏》中就有这个词。写成「窜掇」「撺缀」都不合规范词形。","difficulty":3,"tags":["字形","课内词语"]}]},{"id":"v-ciyu-panshan","title":"蹒跚","subtitle":"词语 · pán shān","grade":"8a","tags":["词语"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"词语"},{"k":"读音","v":"pán shān"}]},{"type":"p","text":"因为腿脚不灵便，走路缓慢、摇摆的样子。"},{"type":"note","title":"易错提示","text":"「蹒」读 pán，「跚」读 shān，两个字都是「足」旁；不能写作「盘珊」「蹒珊」。"},{"type":"quote","text":"父亲蹒跚地走到铁道边，慢慢探身下去。（《背影》）","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-ciyu-panshan-q1","type":"choice","stem":"「蹒跚」中「跚」的正确读音是（ ）","answer":"A","explain":"「跚」读 shān，「蹒跚」形容走路缓慢摇摆的样子，课文《背影》中「父亲蹒跚地走到铁道边」就用这个词写行动的艰难。B 项 shàn 是「扇、善」的读音；C 项 cè 是「册、侧」的读音；D 项 sān 是「三」的读音。","options":["shān","shàn","cè","sān"],"difficulty":3,"tags":["字音","课内词语","易错音"]},{"id":"v-ciyu-panshan-q2","type":"fill","stem":"根据拼音写汉字：父亲 pán shān（ ）地走到铁道边，慢慢探身下去。","answer":"蹒跚","explain":"「蹒跚」写的是腿脚不便、走路缓慢摇摆，与脚的动作有关，因此两个字都是「足」旁。写成「盘珊」「蹒珊」都不合规范词形。","difficulty":3,"tags":["字形","偏旁"]}]},{"id":"v-ciyu-wangran","title":"惘然","subtitle":"词语 · wǎng rán","grade":"9a","tags":["词语"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"词语"},{"k":"读音","v":"wǎng rán"}]},{"type":"p","text":"心里迷茫、若有所失的样子。惘：失意、迷茫。"},{"type":"note","title":"易错提示","text":"「惘」读 wǎng（三声），是「忄」旁，不能写作「罔然」；「茫然」是完全不知道、不知所措，语义侧重不同。"},{"type":"quote","text":"他惘然若失，站在空荡荡的站台上。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-ciyu-wangran-q1","type":"choice","stem":"关于「惘然」，说法正确的一项是（ ）","answer":"A","explain":"「惘」读 wǎng（三声），意为失意、迷茫，「惘然」即心里迷茫、若有所失。B 项把「惘」与「罔」（欺骗、没有）混为一谈；C 项声调错误；D 项读音错误。","options":["读 wǎng rán，「惘」意为失意、迷茫","读 wǎng rán，「惘」意为欺骗","读 wáng rán，「惘」意为失意","读 mǎng rán，「惘」意为迷惘"],"difficulty":3,"tags":["字音","词义","形近字"]},{"id":"v-ciyu-wangran-q2","type":"fill","stem":"根据拼音写汉字：他 wǎng（ ）然若失，站在空荡荡的站台上。","answer":"惘","explain":"「惘」是「忄」旁，表示内心的迷茫失意，故「惘然」写作「惘」。写成「罔」（欺骗、没有）虽同音，但无法表达心理状态。","difficulty":3,"tags":["字形","同音字"]}]},{"id":"v-ciyu-jieju","title":"拮据","subtitle":"词语 · jié jū","grade":"9a","tags":["词语"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"词语"},{"k":"读音","v":"jié jū"}]},{"type":"p","text":"手头不宽裕，缺少钱，境况窘迫。"},{"type":"note","title":"易错提示","text":"「据」在此读 jū（一声），不读 jù（「根据」的音），这是该词最常考的读音。"},{"type":"quote","text":"那时家里生活拮据，母亲事事精打细算。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-ciyu-jieju-q1","type":"choice","stem":"「拮据」中「据」的正确读音是（ ）","answer":"A","explain":"「拮据」读 jié jū，「据」在此读一声 jū，表示经济窘迫。B 项 jù 是「根据、占据」的读音，是本题最常见的误读；C 项 jǔ、D 项 qū 也都不是这个词的读音。","options":["jū","jù","jǔ","qū"],"difficulty":3,"tags":["字音","多音字","课内词语"]},{"id":"v-ciyu-jieju-q2","type":"fill","stem":"根据拼音写汉字：那时家里生活 jié jū（ ），母亲事事精打细算。","answer":"拮据","explain":"「拮据」指手头不宽裕、境况窘迫，两个字都是「扌」旁（本义与手的动作有关），课文《我的叔叔于勒》中用它写家庭的贫困。","difficulty":3,"tags":["字形","课内词语"]}]},{"id":"v-ciyu-zisui","title":"恣睢","subtitle":"词语 · zì suī","grade":"9a","tags":["词语"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"词语"},{"k":"读音","v":"zì suī"}]},{"type":"p","text":"任意胡为。恣：放纵；睢：恣意。"},{"type":"note","title":"易错提示","text":"「睢」读 suī，是「目」旁，容易与「雎」（jū，如《诗经·关雎》）相混，二者形近音义都不同。"},{"type":"quote","text":"我不愿意都如别人的辛苦恣睢而生活。（《故乡》）","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-ciyu-zisui-q1","type":"choice","stem":"「恣睢」中「睢」的正确读音是（ ）","answer":"A","explain":"「睢」读 suī，从「目」，「恣睢」意为任意胡为，课文《故乡》中有「辛苦恣睢而生活」。B 项 jū 是「雎」（如《诗经·关雎》）的读音，两字形近而音不同，是常考辨析点；C 项 zhuī、D 项 cī 也都不是「睢」的读音。","options":["suī","jū","zhuī","cī"],"difficulty":3,"tags":["字音","形近字","课内词语"]},{"id":"v-ciyu-zisui-q2","type":"fill","stem":"「恣睢」意为任意胡为，请写出其中「恣」的意思（ ）。","answer":"放纵","explain":"「恣」是放纵、无拘束的意思，「睢」是恣意、仰视的样子，合起来表示任意胡为。理解「恣」的字义，就能与「姿」（姿态）、「咨」（咨询）等同音字区分开。","difficulty":3,"tags":["词义","课内词语"]}]},{"id":"v-ciyu-xiedu","title":"亵渎","subtitle":"词语 · xiè dú","grade":"9a","tags":["词语"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"词语"},{"k":"读音","v":"xiè dú"}]},{"type":"p","text":"轻慢，不尊敬。亵：轻慢；渎：轻慢、不敬。"},{"type":"note","title":"易错提示","text":"「渎」是「氵」旁，意为轻慢不敬（如「渎职」），不能写作「亵读」「亵黩」。"},{"type":"quote","text":"没有职业的懒人，简直是亵渎职业之神圣。（《敬业与乐业》）","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-ciyu-xiedu-q1","type":"choice","stem":"下列词语书写完全正确的一项是（ ）","answer":"A","explain":"「渎」从「氵」，本义是水沟，引申为轻慢、不敬（如「渎职」），故写作「亵渎」。B 项「读」是诵读；C 项「黩」用于「黩武」（滥用武力）；D 项「泄」是泄漏，都不能表示轻慢不敬。","options":["亵渎","亵读","亵黩","泄渎"],"difficulty":3,"tags":["字形","形近字","课内词语"]},{"id":"v-ciyu-xiedu-q2","type":"fill","stem":"「亵渎」意为轻慢、不尊敬，请写出其中「亵」的意思（ ）。","answer":"轻慢","explain":"「亵」是轻慢、不庄重的意思，与「渎」（轻慢不敬）同义并列，所以「亵渎」表示对神圣事物的不尊重。课文中用它强调敬业的重要。","difficulty":3,"tags":["词义","课内词语"]}]},{"id":"v-ciyu-pangwu","title":"旁骛","subtitle":"词语 · páng wù","grade":"9a","tags":["词语"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"词语"},{"k":"读音","v":"páng wù"}]},{"type":"p","text":"在正业以外有所追求；不专心。骛：追求。"},{"type":"note","title":"易错提示","text":"「骛」是「马」旁（追求，如「好高骛远」），不能写作「旁鹜」（「鹜」是「鸟」旁，指鸭子，如「趋之若鹜」）。"},{"type":"quote","text":"学习要心无旁骛，才能有所收获。","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-ciyu-pangwu-q1","type":"choice","stem":"下列词语书写完全正确的一项是（ ）","answer":"A","explain":"「骛」是「马」旁，本义是马奔驰，引申为追求，「旁骛」即在正业之外另有追求。B 项「鹜」是「鸟」旁，指野鸭（趋之若鹜），二者是常考的形近字；C 项「务」、D 项「傍」都不能构成该词。","options":["旁骛","旁鹜","旁务","傍骛"],"difficulty":3,"tags":["字形","形近字","课内词语"]},{"id":"v-ciyu-pangwu-q2","type":"fill","stem":"成语「心无旁骛」中的「骛」意思是（ ）。","answer":"追求","explain":"「骛」是追求的意思，「心无旁骛」即心里没有另外的追求，形容用心专一。记住「骛」从「马」表追求、「鹜」从「鸟」指鸭子，就不会写错。","difficulty":3,"tags":["词义","形近字"]}]},{"id":"v-ciyu-quanfu","title":"蜷伏","subtitle":"词语 · quán fú","grade":"7a","tags":["词语"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"词语"},{"k":"读音","v":"quán fú"}]},{"type":"p","text":"弯着身体卧着。蜷：弯曲。"},{"type":"note","title":"易错提示","text":"「蜷」读 quán，是「虫」旁，容易与「卷」（juǎn）相混而误读；不能写作「倦伏」「卷伏」。"},{"type":"quote","text":"小猫蜷伏在炉火旁边，睡得正香。（《猫》）","source":"例句"},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-ciyu-quanfu-q1","type":"choice","stem":"「蜷伏」中「蜷」的正确读音是（ ）","answer":"A","explain":"「蜷」读 quán，意为身体弯曲，「蜷伏」即弯着身体卧着，课文《猫》中用它写小猫的睡姿。B 项 juǎn 是「卷」的读音，容易因义近而误读；C 项 quǎn、D 项 chuán 也都不是「蜷」的读音。","options":["quán","juǎn","quǎn","chuán"],"difficulty":2,"tags":["字音","形声字","课内词语"]},{"id":"v-ciyu-quanfu-q2","type":"fill","stem":"根据拼音写汉字：小猫 quán（ ）伏在炉火旁边，睡得正香。","answer":"蜷","explain":"「蜷」是「虫」旁，本义指虫体屈曲，引申为身体弯曲，故「蜷伏」写作「蜷」。写成「倦伏」（疲倦）「卷伏」都不合规范词形。","difficulty":2,"tags":["字形","同音字"]}]},{"id":"v-jinyi-anjing","title":"安静","subtitle":"近义辨析 · ān jìng","grade":"all","tags":["近义辨析"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"近义辨析"},{"k":"读音","v":"ān jìng"}]},{"type":"p","text":"没有声音，没有吵闹和喧哗；也形容人安稳、不吵闹。"},{"type":"note","title":"易错提示","text":"辨析角度——程度轻重与语体色彩：「宁静」程度更重、书面色彩更浓，多形容环境与心境；「安静」更口语，还可以形容人不吵闹（如「请安静」）。"},{"type":"quote","text":"深夜的乡村格外宁静。／老师一进教室，同学们立刻安静下来。","source":"例句"},{"type":"table","title":"易混辨析","head":["易混词","释义"],"rows":[["宁静","（环境、心情）安静、平静。程度比「安静」更重，多带书面语色彩，常与「夜晚、乡村、心境」等搭配。"],["安静","没有声音，不吵闹。口语色彩较强，可形容环境，也可形容人安稳不吵闹。"]]},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-jinyi-anjing-q1","type":"choice","stem":"依次填入下列句子横线处最恰当的一项是（ ）①深夜的乡村格外____。②老师一进教室，同学们立刻____下来。","answer":"A","explain":"①处形容深夜乡村的环境，用书面色彩浓、程度更重的「宁静」更贴切；②处是要求同学们不吵闹，是口语化的用法，只能用「安静」。二者最主要的区别就是：形容人「不吵闹」时只能选「安静」，不能说「请宁静」。","options":["宁静　安静","安静　宁静","宁静　宁静","安静　安静"],"difficulty":2,"tags":["近义辨析","程度轻重","语体色彩"]},{"id":"v-jinyi-anjing-q2","type":"fill","stem":"请写出与「安静」意思相近，但程度更重、多用于书面语的词语（ ）。","answer":"宁静","explain":"「宁静」与「安静」都表示没有喧闹，但「宁静」程度更重、书面色彩更浓，常用来写夜晚、乡村的环境或内心的平和，因而显得更庄重。","difficulty":2,"tags":["近义辨析","语体色彩"]}]},{"id":"v-jinyi-ningshi","title":"凝视","subtitle":"近义辨析 · níng shì","grade":"all","tags":["近义辨析"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"近义辨析"},{"k":"读音","v":"níng shì"}]},{"type":"p","text":"聚精会神地看，目不转睛地看，看的时间较长。对象多为具体的人或物。"},{"type":"note","title":"易错提示","text":"辨析角度——时间长短与搭配对象：「凝视」强调长时间目不转睛，对象多为具体的人或物；「注视」强调注意力集中地看，时间可长可短，还可带抽象宾语（注视局势的发展）。"},{"type":"quote","text":"他久久凝视着那张泛黄的老照片。／全世界都在注视着这个国家的局势。","source":"例句"},{"type":"table","title":"易混辨析","head":["易混词","释义"],"rows":[["注视","注意地看，视线集中。时间可长可短，对象可以是具体事物，也可以是抽象事物（如注视着事态的发展）。"],["凝视","目不转睛地看，聚精会神地看，时间较长，含专注、深情的意味，对象多为具体的人或物。"]]},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-jinyi-ningshi-q1","type":"choice","stem":"依次填入下列句子横线处最恰当的一项是（ ）①他久久____着那张泛黄的老照片。②全世界都在____着这个国家的局势。","answer":"A","explain":"①处有「久久」一词，强调长时间不转眼地看具体事物，用「凝视」；②处的对象是抽象的「局势」，含有「密切关注」的意思，只能用「注视」。「凝视」不能带抽象宾语。","options":["凝视　注视","注视　凝视","凝视　凝视","注视　注视"],"difficulty":2,"tags":["近义辨析","搭配对象"]},{"id":"v-jinyi-ningshi-q2","type":"choice","stem":"下列关于「凝视」与「注视」的说法，正确的一项是（ ）","answer":"B","explain":"「凝视」指目不转睛地看，时间较长，对象多为具体的人或物，B 项正确。A 项忽略了二者的差别；C 项错误地把「长时间」说成「注视」的唯一特点；D 项「凝视未来」搭配不当，表示关注抽象事物应用「展望」「注视」。","options":["二者完全同义，可以随意换用","「凝视」强调长时间目不转睛，对象多为具体的人或物","「注视」只能表示长时间地看同一个地方","「凝视」可以带抽象宾语，如「凝视未来」"],"difficulty":3,"tags":["近义辨析","搭配对象"]}]},{"id":"v-jinyi-hushi","title":"忽视","subtitle":"近义辨析 · hū shì","grade":"all","tags":["近义辨析"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"近义辨析"},{"k":"读音","v":"hū shì"}]},{"type":"p","text":"不注意，不重视。多因疏忽大意而没有注意到，程度较轻，常指无意的疏忽。"},{"type":"note","title":"易错提示","text":"辨析角度——程度轻重与是否故意：「忽视」偏无意疏忽；「无视」是故意不放在眼里、根本不考虑，程度更重，常带谴责色彩。"},{"type":"quote","text":"不能忽视安全教育，否则容易出事故。／他无视校规，多次无故旷课。","source":"例句"},{"type":"table","title":"易混辨析","head":["易混词","释义"],"rows":[["无视","不放在眼里，根本不考虑，含有故意、蔑视的意味。程度比「忽视」重，常带谴责色彩（无视纪律、无视事实）。"],["忽视","因疏忽或不重视而没有注意到。程度较轻，多为无意的疏漏，如「忽视细节」。"]]},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-jinyi-hushi-q1","type":"choice","stem":"依次填入下列句子横线处最恰当的一项是（ ）①不能____安全教育，否则容易出事故。②他____校规，多次无故旷课。","answer":"A","explain":"①处指因不重视而漏掉了安全教育，语意较轻，用「忽视」；②处是故意不把校规放在眼里，含有谴责意味，程度更重，用「无视」。②处若用「忽视」，就丢掉了「故意蔑视」的意思。","options":["忽视　无视","无视　忽视","忽视　忽视","无视　无视"],"difficulty":2,"tags":["近义辨析","程度轻重","感情色彩"]},{"id":"v-jinyi-hushi-q2","type":"fill","stem":"表示「故意不放在眼里、根本不考虑」的词语是（ ）。","answer":"无视","explain":"「无视」含有故意不理会、轻视的意味，程度比「忽视」重，如「无视纪律」「无视事实」。而「忽视」多指因疏忽而没注意到，没有「故意」的意思。","difficulty":2,"tags":["近义辨析","程度轻重"]}]},{"id":"v-jinyi-guoduan","title":"果断","subtitle":"近义辨析 · guǒ duàn","grade":"all","tags":["近义辨析"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"近义辨析"},{"k":"读音","v":"guǒ duàn"}]},{"type":"p","text":"有决断，办事不犹豫。含褒义，形容人处理事情坚决、及时。"},{"type":"note","title":"易错提示","text":"辨析角度——感情色彩：「果断」是褒义（果断处理）；「武断」是贬义（只凭主观判断、不听意见）。二者都含「决断快」的意思，但感情色彩相反。"},{"type":"quote","text":"情况紧急，他果断地下达了撤退的命令。／不做调查就下结论，未免太武断。","source":"例句"},{"type":"table","title":"易混辨析","head":["易混词","释义"],"rows":[["武断","只凭主观判断，不听别人意见，轻率地做决定或下结论。含贬义。"],["果断","有决断，办事坚决、不犹豫。含褒义。"]]},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-jinyi-guoduan-q1","type":"choice","stem":"依次填入下列句子横线处最恰当的一项是（ ）①情况紧急，连长____地下达了撤退命令。②他不听任何意见就下了结论，实在太____。","answer":"A","explain":"①处是紧急情况下坚决及时地作出决定，含褒义，用「果断」；②处是不听意见、主观下结论，含贬义，用「武断」。二者的主要区别在感情色彩，用反了就会褒贬失当。","options":["果断　武断","武断　果断","果断　果断","武断　武断"],"difficulty":1,"tags":["近义辨析","感情色彩"]},{"id":"v-jinyi-guoduan-q2","type":"fill","stem":"与「果断」意思相近但含贬义、指「只凭主观判断」的词语是（ ）。","answer":"武断","explain":"「武断」指只凭主观判断、不听别人意见就作决定，是贬义词；「果断」则是褒义，指有决断、不犹豫。辨析这类近义词，首先要看感情色彩。","difficulty":2,"tags":["近义辨析","感情色彩"]}]},{"id":"v-jinyi-jiezhi","title":"截至","subtitle":"近义辨析 · jié zhì","grade":"all","tags":["近义辨析"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"近义辨析"},{"k":"读音","v":"jié zhì"}]},{"type":"p","text":"到（某个时候）为止。后面必须带表示时间的词语，如「截至6月底」。"},{"type":"note","title":"易错提示","text":"辨析角度——词性与搭配：「截止」是不及物动词，后面不能带时间宾语（说「6月30日截止」）；「截至」后面必须带时间宾语（说「截至6月30日」）。"},{"type":"quote","text":"报名工作已于昨天截止。／截至6月底，全市新增绿地50公顷。","source":"例句"},{"type":"table","title":"易混辨析","head":["易混词","释义"],"rows":[["截止","（到一定期限）停止。是不及物动词，后面不能带宾语，通常说「某日截止」。"],["截至","到某时为止。后面必须带表示时间的宾语，如「截至5月底」。"]]},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-jinyi-jiezhi-q1","type":"choice","stem":"依次填入下列句子横线处最恰当的一项是（ ）①报名工作已于昨天____。②___₆月底，全市新增绿地50公顷。","answer":"A","explain":"①处「截止」后面没有宾语，表示「到期限停止」，用「截止」；②处后面带了时间宾语「6月底」，必须用「截至」。这是二者的核心区别：「截止」不及物，「截至」必须带时间宾语。","options":["截止　截至","截至　截止","截止　截止","截至　截至"],"difficulty":3,"tags":["近义辨析","搭配对象","词性"]},{"id":"v-jinyi-jiezhi-q2","type":"choice","stem":"下列句子中词语使用正确的一项是（ ）","answer":"C","explain":"「截至」后面可以带时间宾语，「截至目前」搭配正确，C 项对。A 项「截止」后带了宾语「目前」，搭配不当；B、D 两项该用不及物的「截止」，却用了「截至」，同样不当。","options":["截止目前，报名人数已超过一千。","报名时间已于昨日截至。","截至目前，报名人数已超过一千。","报名日期不得随意截至。"],"difficulty":3,"tags":["近义辨析","搭配对象"]}]},{"id":"v-jinyi-bixu","title":"必须","subtitle":"近义辨析 · bì xū","grade":"all","tags":["近义辨析"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"近义辨析"},{"k":"读音","v":"bì xū"}]},{"type":"p","text":"副词，表示事理上和情理上的必要，一定要。后面跟动词或形容词，如「必须遵守」。"},{"type":"note","title":"易错提示","text":"辨析角度——词性与搭配：「必须」是副词，修饰动词（必须努力）；「必需」是形容词，多修饰名词（必需品、必需的条件）。"},{"type":"quote","text":"我们必须遵守交通规则。／水和空气是人类必需的物质。","source":"例句"},{"type":"table","title":"易混辨析","head":["易混词","释义"],"rows":[["必需","形容词，必不可少的。多作定语修饰名词，如「必需品」「必需的条件」，也可作谓语，如「空气和水是人类必需的」。"],["必须","副词，表示一定要。修饰动词或形容词，如「必须完成」「必须认真」。"]]},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-jinyi-bixu-q1","type":"choice","stem":"依次填入下列句子横线处最恰当的一项是（ ）①我们____遵守交通规则。②粮食是人们生活的____品。","answer":"A","explain":"①处修饰动词「遵守」，表示「一定要」，用副词「必须」；②处修饰名词「品」，表示「不可缺少的」，用形容词「必需」。判断的关键是看后面跟的是动词还是名词。","options":["必须　必需","必需　必须","必须　必须","必需　必需"],"difficulty":2,"tags":["近义辨析","词性","搭配对象"]},{"id":"v-jinyi-bixu-q2","type":"choice","stem":"下列句子中词语使用正确的一项是（ ）","answer":"C","explain":"「必需」是形容词，可作谓语，「空气和水是人类必需的」搭配正确，C 项对。A 项应为「必需品」（形容词修饰名词）；B 项「必须的」不能作定语修饰名词，应为「必需的」；D 项修饰动词「出发」应用副词「必须」。","options":["这是生活必须品。","我们必须的生活用品都准备好了。","空气和水是人类必需的。","你必需马上出发。"],"difficulty":3,"tags":["近义辨析","词性"]}]},{"id":"v-jinyi-qishi","title":"启示","subtitle":"近义辨析 · qǐ shì","grade":"all","tags":["近义辨析"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"近义辨析"},{"k":"读音","v":"qǐ shì"}]},{"type":"p","text":"启发提示，使有所领悟；也指从某事中得到的启发。可作动词，也可作名词。"},{"type":"note","title":"易错提示","text":"辨析角度——词义与使用场合：「启示」是启发领悟，可作动词；「启事」是为了公开声明某事而登在报刊上或贴在墙上的文字，只能作名词。"},{"type":"quote","text":"这件事给了我很大的启示。／门口贴着一张寻人启事。","source":"例句"},{"type":"table","title":"易混辨析","head":["易混词","释义"],"rows":[["启事","为了公开声明某事而登在报刊上或贴在墙上的文字，如「招领启事」「寻人启事」。只能作名词。"],["启示","启发开导，使人有所领悟；也指由此得到的启发、领悟。可作动词，也可作名词。"]]},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-jinyi-qishi-q1","type":"choice","stem":"依次填入下列句子横线处最恰当的一项是（ ）①这次社会实践给了我很大的____。②墙上贴着一张招领____。","answer":"A","explain":"①处指从中得到的启发，用「启示」；②处指公开声明事情的文字，用「启事」。二者的区别在于「启示」是启发领悟，「启事」是公开告知的文字，只能作名词。","options":["启示　启事","启事　启示","启示　启示","启事　启事"],"difficulty":2,"tags":["近义辨析","同音词","词性"]},{"id":"v-jinyi-qishi-q2","type":"fill","stem":"表示「为公开声明某事而登在报刊上或贴在墙上的文字」的词语是（ ）。","answer":"启事","explain":"「启事」是一种公开声明事情的文字，如「招领启事」「寻人启事」「征文启事」，只能作名词；「启示」是启发领悟，可作动词，如「这本书启示我们要珍惜时间」。","difficulty":2,"tags":["近义辨析","同音词"]}]},{"id":"v-jinyi-cuangai","title":"篡改","subtitle":"近义辨析 · cuàn gǎi","grade":"all","tags":["近义辨析"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"近义辨析"},{"k":"读音","v":"cuàn gǎi"}]},{"type":"p","text":"用作伪的手段改动或曲解（经典、理论、政策、历史等）。含贬义，程度较重。"},{"type":"note","title":"易错提示","text":"辨析角度——对象与色彩：「窜改」多指文字、成语、古书上的错误改动；「篡改」强调出于不良目的歪曲、作伪，对象常是历史、理论、政策，贬义更重。"},{"type":"quote","text":"历史不容篡改。／这篇文章引用时窜改了几处原文。","source":"例句"},{"type":"table","title":"易混辨析","head":["易混词","释义"],"rows":[["窜改","改动（成语、文件、古书等）。多指文字上的错误改动，不含「歪曲作伪」的意味。"],["篡改","用作伪的手段改动或曲解，对象多为历史、理论、政策等，含贬义，程度更重。"]]},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-jinyi-cuangai-q1","type":"choice","stem":"依次填入下列句子横线处最恰当的一项是（ ）①历史不容____。②引用原文时不能随意____文字。","answer":"A","explain":"①处的对象是「历史」，指用伪造手段歪曲，贬义重，用「篡改」；②处的对象是具体的「文字」，指文字上的改动，用「窜改」。判断时先看对象是抽象的历史、理论，还是具体的文字。","options":["篡改　窜改","窜改　篡改","篡改　篡改","窜改　窜改"],"difficulty":3,"tags":["近义辨析","搭配对象","感情色彩"]},{"id":"v-jinyi-cuangai-q2","type":"fill","stem":"指「用作伪手段改动或曲解历史、理论」的词语是（ ）。","answer":"篡改","explain":"「篡改」强调用作伪的手段改动或曲解，贬义较重，常用于历史、理论、政策等；「窜改」则多指文字上、书本上的改动。二者读音相同，要根据对象和色彩区分。","difficulty":3,"tags":["近义辨析","搭配对象"]}]},{"id":"v-jinyi-quanli","title":"权利","subtitle":"近义辨析 · quán lì","grade":"all","tags":["近义辨析"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"近义辨析"},{"k":"读音","v":"quán lì"}]},{"type":"p","text":"公民或法人依法享有的权益。常与「义务」相对。"},{"type":"note","title":"易错提示","text":"辨析角度——词义侧重：「权力」侧重强制、支配的力量，主体多为国家机关、公职人员；「权利」侧重依法享有的利益，主体多为公民、法人。"},{"type":"quote","text":"要依法保障公民的合法权利。／国家机关必须在法律范围内行使权力。","source":"例句"},{"type":"table","title":"易混辨析","head":["易混词","释义"],"rows":[["权力","政治上的强制力量，或职责范围内的支配力量。主体多为国家机关、公职人员，如「国家权力」「行使权力」。"],["权利","公民或法人依法享有的权益，如「受教育的权利」「选举权」。常与「义务」相对。"]]},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-jinyi-quanli-q1","type":"choice","stem":"依次填入下列句子横线处最恰当的一项是（ ）①每个公民都享有受教育的____。②国家工作人员必须依法行使____。","answer":"A","explain":"①处的主语是「公民」，指依法享有的权益，用「权利」；②处指国家机关及其工作人员的支配力量，用「权力」。判断的关键是看主体：属于公民、法人的是「权利」，属于国家机关的是「权力」。","options":["权利　权力","权力　权利","权利　权利","权力　权力"],"difficulty":2,"tags":["近义辨析","同音词","搭配对象"]},{"id":"v-jinyi-quanli-q2","type":"fill","stem":"与「义务」相对、指公民依法享有的权益的词语是（ ）。","answer":"权利","explain":"「权利」指公民或法人依法享有的权益，常与「义务」相对举；「权力」指政治上的强制力量或职责范围内的支配力量，主体多为国家机关和公职人员。","difficulty":2,"tags":["近义辨析","同音词"]}]},{"id":"v-xiuci-duiou","title":"对偶","subtitle":"修辞手法 · duì ǒu","grade":"all","tags":["修辞手法"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"修辞手法"},{"k":"读音","v":"duì ǒu"}]},{"type":"p","text":"用两个字数相等、结构相同或相似、词性相对、意义相关的一对短语或句子，成对地排列起来的修辞手法。构成特点是「四相等」：字数相等、结构相同、词性相对、意义相关（意义上或相近、或相反、或相承）。表达效果是形式整齐匀称、节奏鲜明、音韵和谐、便于记诵，两两对照还能使意思表达得凝练含蓄，富有对称美。"},{"type":"note","title":"易错提示","text":"对偶最易与对比、排比混淆，辨析要点有三条。一是与对比的区别：对偶着眼于形式，要求字数相等、结构对称、词性相对，求的是「对称」之美；对比着眼于内容，只要求把两个相反或相对的事物（或同一事物的两个方面）并举比较，求的是「对立」之效，不要求字数相等、结构相同。所以两项既字数相等、结构相同，又内容对立，是对偶兼对比，如「横眉冷对千夫指，俯首甘为孺子牛」；两项只内容对立而字数不等、结构不齐，只是对比，如「有的人活着，他已经死了；有的人死了，他还活着」中的前后对照；两项只形式对称而内容并不对立，只是对偶，如「两个黄鹂鸣翠柳，一行白鹭上青天」写的是两幅相衬的春景，并无相反相对之意。二是与排比的区别：对偶必须两项，且字数相等、结构相同、词性相对，讲究「成对」；排比必须三项或三项以上，只要求结构相似、语气一致、内容相关，字数可以不完全相等，讲究「铺排」。因此凡三项以上连排即可断定为排比，绝不会是对偶。三是答题口诀：先数项数（两项才可能是对偶，三项以上是排比），再看形式（字数是否相等、结构是否相同），最后看意图（重形式对称还是重内容对立）。"},{"type":"quote","text":"两个黄鹂鸣翠柳，一行白鹭上青天。（杜甫《绝句》）\n无边落木萧萧下，不尽长江滚滚来。（杜甫《登高》）\n苔痕上阶绿，草色入帘青。（刘禹锡《陋室铭》）\n横眉冷对千夫指，俯首甘为孺子牛。（鲁迅《自嘲》）\n田野里麦浪翻滚，山坡上果香四溢。（现代文例句）","source":"例句"},{"type":"table","title":"易混辨析","head":["易混词","释义"],"rows":[["对比","把两个相反或相对的事物（或同一事物的两个方面）并举比较，重在内容对立，不要求字数相等、结构对称。与对偶的区别是：对偶重形式对称，对比重内容对立。"],["排比","三个或三个以上结构相似、语气一致的短语或句子连用，重在铺排气势，字数可以不完全相等。与对偶的区别是项数：对偶恰好两项且字数相等，排比必须三项以上。"]]},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-xiuci-duiou-q1","type":"choice","stem":"「两个黄鹂鸣翠柳，一行白鹭上青天」运用的修辞手法是（ ）","answer":"B","explain":"这两句各七个字，字数相等；结构相同，都是「数量词＋名词＋动词＋名词」；词性相对，「两个」对「一行」、「黄鹂」对「白鹭」、「鸣」对「上」、「翠柳」对「青天」，是标准的对偶。句中只写两幅相衬的春日景物，没有相反或相对的内容，所以不是对比；只有两项，不符合排比三项以上的要求；句中没有原样重复同一词语，也不是反复。","options":["对比","对偶","排比","反复"],"difficulty":1,"tags":["修辞","对偶"]},{"id":"v-xiuci-duiou-q2","type":"choice","stem":"下列对对偶这一修辞表达效果的分析，最恰当的一项是（ ）","answer":"A","explain":"对偶的表达效果主要是形式整齐、节奏鲜明、音韵和谐、便于记诵，同时两两对照使表达凝练，A 项正确。B 项说的是设问，C 项说的是反复，D 项说的是排比，都不是对偶的作用。答这类题要看修辞的形式特点：对偶成双成对、字数相等，功效首先落在形式与节奏上。","options":["形式整齐匀称，节奏鲜明，读来朗朗上口，便于记诵，并使前后两句互相映衬","先提出问题再自己回答，以引起读者注意，突出所要强调的内容","让同一个词语反复出现，以强调某种情感、增强语势","把三个以上结构相似的句子连用，使语言气势磅礴、层层推进"],"difficulty":2,"tags":["修辞","对偶","表达效果"]},{"id":"v-xiuci-duiou-q3","type":"fill","stem":"用两个字数相等、结构相同、词性相对、意义相关的短语或句子成对排列，这种修辞手法叫（ ）。","answer":"对偶","explain":"这是对偶的定义。其构成特点是字数相等、结构相同、词性相对、意义相关；表达效果是形式整齐、节奏鲜明、便于记诵。注意与「对比」分开：对比只要求内容对立，不要求形式对称。","difficulty":2,"tags":["修辞","对偶","定义"]},{"id":"v-xiuci-duiou-q4","type":"choice","stem":"下列关于对偶与对比、对偶与排比的区别，说法正确的一项是（ ）","answer":"A","explain":"对偶是形式上的要求，讲字数相等、结构相同、词性相对；对比是内容上的要求，只把相反或相对的事物并举比较，不拘字数与结构，A 项正确。B 项混淆了两种修辞；C 项前半句正确，但排比只要求结构相似、语气一致，字数可以不完全相等，「必须完全相等」是错的；D 项项数说错，三项以上连排的正是排比，对偶恰好两项。","options":["对偶重形式对称，要求字数相等、结构相同；对比重内容对立，不要求字数相等、结构对称","对偶与对比是同一种修辞手法的两种叫法，可以随意换用","排比必须三项或三项以上，而且各项字数必须完全相等","对偶可以是三项或三项以上，只要结构大致相似即可"],"difficulty":3,"tags":["修辞","对偶","易混辨析"]}]},{"id":"v-xiuci-fanfu","title":"反复","subtitle":"修辞手法 · fǎn fù","grade":"all","tags":["修辞手法"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"修辞手法"},{"k":"读音","v":"fǎn fù"}]},{"type":"p","text":"为了强调某种意思、突出某种情感，有意让同一个词语、短语或句子一再出现的修辞手法。构成特点是「同一语言单位有意重复」：可以是连续反复，同一语句紧接重复（如「盼望着，盼望着」）；也可以是间隔反复，同一语句在文中隔开反复出现（如《安塞腰鼓》中多次出现「好一个安塞腰鼓」）。表达效果是突出强调、增强语势、强化情感、加深印象，使语言有回环往复的节奏美；间隔反复还能分清层次、前后照应，使文章脉络更清楚。"},{"type":"note","title":"易错提示","text":"反复既要与排比严格分开，也要与重复啰嗦严格分开。一是与排比的区别：反复重复的是「同一语言单位」，同一个词语或句子原样再现，重复的是字面，两项即可成立，如「盼望着，盼望着」；排比重复的是「结构形式」，三个或三个以上结构相似、语气一致、内容相关的短语或句子连用，字面一般各不相同，如「他们的品质是那样的纯洁和高尚，他们的意志是那样的坚韧和刚强」。判断口诀是：反复看字面是否原样重复，排比看结构是否相似、项数是否在三项以上。二是与重复啰嗦的区别：反复是主动的修辞手段，为强调情感、增强语势而有意重复，删去重复部分会削弱情感与气势；重复啰嗦是语言毛病，指没有表达需要地重复同一个意思或词语，删去后句子更简洁。判断的关键是「有没有表达需要」：「沉默呵，沉默呵」删去一个就失去了压抑呼告的力量，是反复；「他大约估计可能有二十人左右」叠用了三个表推测的词语，并无表达需要，是啰嗦。"},{"type":"quote","text":"盼望着，盼望着，东风来了，春天的脚步近了。（朱自清《春》，连续反复）\n沉默呵，沉默呵！不在沉默中爆发，就在沉默中灭亡。（鲁迅《记念刘和珍君》，连续反复）\n周总理，我们的好总理，你在哪里呵，你在哪里？（柯岩《周总理，你在哪里》）\n好一个安塞腰鼓！（刘成章《安塞腰鼓》，文中多次间隔出现，属间隔反复）","source":"例句"},{"type":"table","title":"易混辨析","head":["易混词","释义"],"rows":[["排比","三个或三个以上结构相似、语气一致的短语或句子连用，重复的是结构形式，字面一般各不相同，作用是增强语势、层层铺排。与反复的区别是：反复重复字面、两项即可。"],["重复啰嗦","语言表达上的毛病，指没有表达需要地重复同一个意思或词语，删去后表达更简洁。反复是有意强调的修辞，啰嗦是无意造成的赘余。"]]},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-xiuci-fanfu-q1","type":"choice","stem":"「盼望着，盼望着，东风来了，春天的脚步近了。」这句运用的修辞手法是（ ）","answer":"B","explain":"句中「盼望着」原样重复出现，是同一词语的连续反复，强调了对春天的急切期盼。它不是排比，因为排比须三项以上、结构相似而字面一般不同；两句结构也不构成对偶，因为不满足字数相等、词性相对的要求；句中没有任何提问，更不是设问。","options":["排比","反复","对偶","设问"],"difficulty":1,"tags":["修辞","反复"]},{"id":"v-xiuci-fanfu-q2","type":"choice","stem":"下列对「沉默呵，沉默呵！不在沉默中爆发，就在沉默中灭亡」中反复手法的表达效果分析，最恰当的一项是（ ）","answer":"A","explain":"「沉默呵，沉默呵」是呼告式的连续反复，把作者压抑已久的悲愤推向高潮，并顺势引出「不在沉默中爆发，就在沉默中灭亡」的论断，A 项正确。B 项说的是设问，句中并没有自问自答；C 项说的是对偶或对比，与本句的重复形式无关；D 项把反复误解为啰嗦，反复是为强调情感而有意为之，不是为了拉长篇幅。","options":["反复呼告「沉默呵」，把压抑已久的悲愤推向高潮，表现出作者的痛心与对爆发的呼唤，增强了语势","先提问再自己回答，引起读者对「沉默」这一话题的注意","以字数相等、结构对称的形式，写出沉默与爆发两个方面的对立","重复出现是为了把篇幅拉长，使句子读起来更完整"],"difficulty":2,"tags":["修辞","反复","表达效果"]},{"id":"v-xiuci-fanfu-q3","type":"fill","stem":"为了强调某种意思、突出某种情感，有意让同一个词语或句子一再出现，这种修辞手法叫（ ）。","answer":"反复","explain":"这是反复的定义。反复分连续反复与间隔反复，作用是突出强调、增强语势、强化情感。要与「重复啰嗦」区分：反复是有表达需要的修辞手段，啰嗦是无表达需要的语言赘余。","difficulty":1,"tags":["修辞","反复","定义"]},{"id":"v-xiuci-fanfu-q4","type":"choice","stem":"下列关于反复与排比、反复与重复啰嗦的说法，正确的一项是（ ）","answer":"A","explain":"反复重复的是同一语言单位，字面原样再现，两项即可，如「盼望着，盼望着」；排比重复的是结构形式，须三项以上且字面一般不同，A 项正确。B 项错在反复两项即可；C 项错在把修辞手段说成语言毛病，反复是有意强调，啰嗦是无意赘余；D 项把二者的特点说反了。","options":["反复是同一个词语或句子原样重复，排比是三个以上结构相似的短语或句子连用，二者重复的对象不同","反复和排比都必须三项以上，否则不能成立","反复就是重复啰嗦，两者都是语言表达上的毛病","排比要求各项字面完全相同，反复要求各项结构相似"],"difficulty":3,"tags":["修辞","反复","易混辨析"]}]},{"id":"v-xiuci-shewen","title":"设问","subtitle":"修辞手法 · shè wèn","grade":"all","tags":["修辞手法"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"修辞手法"},{"k":"读音","v":"shè wèn"}]},{"type":"p","text":"为了引起读者注意、启发读者思考，先自己提出一个问题，然后自己回答的修辞手法。构成特点是「无疑而问、自问自答」：作者心里早有答案，提问只是手段，回答（或由提问引出的内容）才是要强调的重点。表达效果是提醒注意、引发思考、突出强调所要表达的内容，使行文有波澜、层次分明，重点更加醒目；设问常用在篇首、段首以提纲挈领、引出下文，也可用在段中起过渡作用。"},{"type":"note","title":"易错提示","text":"设问的易错点在于它与反问、与一般疑问句的界限。一是与反问的区别：设问是自问自答，答案在问句之外，由作者自己说出来，如「谁是我们最可爱的人呢？我们的战士，我感到他们是最可爱的人」；反问是问而不答，答案就在问句之中，用疑问的形式表达确定的意思，不需回答，如「难道我们能浪费时间吗」意思就是「我们不能浪费时间」。判断的关键是看问句后面有没有回答，或问句本身是否已把意思说明白：另有回答的是设问，问句本身已说清而无需再答的是反问。二是与一般疑问句的区别：一般疑问句是「有疑而问」，作者确实不知道答案，要靠对方提供，如「请问去车站怎么走」；设问是「无疑而问」，作者心中早有答案，提问只是为了引起注意、突出下文，因此设问的答案一定能在上下文里找到，而一般疑问句的答案要由别人给出。三是注意作用表述不可混：设问的常见作用是「引起注意、启发思考、突出强调」，反问的常见作用是「加强语气、鲜明有力」，把设问答成「加强了语气」，就是与反问弄混了。"},{"type":"quote","text":"谁是我们最可爱的人呢？我们的战士，我感到他们是最可爱的人。（魏巍《谁是最可爱的人》）\n为什么我国的石拱桥会有这样光辉的成就呢？首先，在于我国劳动人民的勤劳和智慧。（茅以升《中国石拱桥》）\n花儿为什么这样红？首先有它的物质基础。（贾祖璋《花儿为什么这样红》）\n什么是英雄？英雄就是在危难时刻挺身而出的普通人。（现代文例句）","source":"例句"},{"type":"table","title":"易混辨析","head":["易混词","释义"],"rows":[["反问","用疑问的形式表达确定的意思，答案就在问句之中，不需回答。与设问的区别是：反问问中有答，设问自问自答、答案在问句之外。"],["一般疑问句","有疑而问，作者确实不知道答案而提问，要求对方回答，不含引起注意、突出强调的修辞意图。与设问的区别是「有疑」与「无疑」。"]]},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-xiuci-shewen-q1","type":"choice","stem":"「谁是我们最可爱的人呢？我们的战士，我感到他们是最可爱的人。」这句运用的修辞手法是（ ）","answer":"B","explain":"前一句提出问题，后一句自己作答，是典型的自问自答，故选设问。反问只问不答、答案已在问句之中，而本句作者明确给出了答案，所以不是反问；句中没有原样重复同一词语，不是反复；前后两句字数不等、结构不相对，不是对偶。","options":["反问","设问","反复","对偶"],"difficulty":1,"tags":["修辞","设问"]},{"id":"v-xiuci-shewen-q2","type":"choice","stem":"下列对设问这一修辞表达效果的分析，最恰当的一项是（ ）","answer":"A","explain":"设问的作用是引起注意、启发思考、突出强调，A 项正确。B 项说的是反问，「答案在问句中、加强语气」正是反问的特点；C 项说的是排比；D 项说的是反复。区分设问与反问，关键看答案的位置：答案在问句之外的是设问，在问句之中的是反问。","options":["先提出问题引起读者注意和思考，再自己作答，突出强调了所要表达的内容，使行文有波澜","答案就在问句之中，用疑问的形式加强语气，使意思表达得更强烈","把三个以上结构相似的句子连用，使语言气势磅礴","让同一个词语反复出现，以强调某种情感、加深印象"],"difficulty":2,"tags":["修辞","设问","表达效果"]},{"id":"v-xiuci-shewen-q3","type":"fill","stem":"先自己提出问题、再自己回答，以引起读者注意、突出所要表达的内容，这种修辞手法叫（ ）。","answer":"设问","explain":"这是设问的定义，特点是「无疑而问、自问自答」，答案在问句之外。应与「问而不答、答案在问句中」的反问区分：反问不需要回答，设问必须由作者自己作答。","difficulty":1,"tags":["修辞","设问","定义"]},{"id":"v-xiuci-shewen-q4","type":"choice","stem":"下列对设问与反问的区分，正确的一项是（ ）","answer":"A","explain":"二者的根本区别在于答案的位置：设问自问自答，答案在问句之外，作者借提问引出要强调的内容；反问问而不答，答案已在问句之中，用疑问的形式表达确定的意思，A 项正确。B 项错在两者不能随意换用，作用也不相同；C 项恰好把二者说反；D 项把两者的定义调换了。","options":["设问是自问自答，答案在问句之外；反问是答案就在问句之中，不需要回答","设问和反问都不需要回答，可以把两者随意换用","设问要由读者来回答，反问由作者自己回答","设问用疑问的形式表达确定的意思，反问是先提问再自己作答"],"difficulty":3,"tags":["修辞","设问","易混辨析"]}]},{"id":"v-xiuci-fanwen","title":"反问","subtitle":"修辞手法 · fǎn wèn","grade":"all","tags":["修辞手法"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"修辞手法"},{"k":"读音","v":"fǎn wèn"}]},{"type":"p","text":"用疑问的形式表达确定的意思，答案就在问句之中、不需要回答的修辞手法，也叫反诘、激问。构成特点是「无疑而问、问中有答」：形式上是问句，意思上却是确定的陈述，常借「难道」「岂」「怎么」「怎能」「何尝」「安能」等词语加强语气。表达效果是加强语气、鲜明有力，把本来确定的意思表达得更强烈、更不容置疑，从而引起读者思考，增强文章的感染力和说服力。"},{"type":"note","title":"易错提示","text":"反问的易错点有三个方面。一是与设问的区别：设问自问自答，先提问后作答，答案在问句之外；反问只问不答，答案就在问句之中，用疑问的形式表达确定的意思。判断方法是看问句后面有没有另给答案，另有回答的是设问，问句本身已把意思说清、无须再答的是反问。二是反问句改陈述句的方法，分两步：第一步去掉「难道」「岂」「怎么」「怎能」「何尝」「不也」等疑问语气词和句末的问号，把问号改成句号；第二步做「否定之否定」的转换——原句中有「不、没有、无、非」等否定词的，改后要去掉否定词，原句中没有否定词的，改后要加上否定词，这样意思才与原文一致。例如「难道我们不应该珍惜今天的幸福生活吗」应改为「我们应该珍惜今天的幸福生活」。三是「否定之否定」表肯定：反问句中出现「难道不」「怎能不」「不是」「不也」这类双重否定的，表达的是强烈的肯定，如「难道这不是奇迹吗」意思是「这是奇迹」；反问句中没有否定词的，表达的是强烈的否定，如「难道我们能浪费时间吗」意思是「我们不能浪费时间」，「我怎么会忘记呢」意思是「我不会忘记」。答题时切忌只把问号改成句号而不处理否定词，那样会把意思弄反。"},{"type":"quote","text":"王侯将相宁有种乎！（司马迁《史记·陈涉世家》）——用反问表达强烈的否定，意思是「王侯将相并不是天生的贵种」。\n燕雀安知鸿鹄之志哉！（司马迁《史记·陈涉世家》）——意思是「燕雀不会知道鸿鹄的志向」。\n安能摧眉折腰事权贵，使我不得开心颜！（李白《梦游天姥吟留别》）\n难道我们能因为一次失败就放弃努力吗？（现代文例句）——意思是「我们不能因为一次失败就放弃努力」。","source":"例句"},{"type":"table","title":"易混辨析","head":["易混词","释义"],"rows":[["设问","自问自答，先提出问题引起注意，再自己给出答案，答案在问句之外。与反问的区别是答案的位置不同。"],["一般疑问句","有疑而问，确实不知道答案而提问，要求对方回答，不含加强语气的意图。与反问的区别是反问「无疑而问」，答案已在问中。"],["双重否定句","用两个否定词表达肯定的意思，如「不能不珍惜」。它与反问的「否定之否定」都能表示强烈的肯定，但双重否定句是陈述句形式，反问是疑问句形式，且反问不需回答。"]]},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-xiuci-fanwen-q1","type":"choice","stem":"「难道我们能浪费时间吗？」这句话的修辞手法和意思是（ ）","answer":"B","explain":"本句有「难道……吗」这一反问标志，只问不答而意思明确，是反问；「难道」加肯定形式表达的是强烈的否定，意思是「我们不能浪费时间」，故选 B。A 项误判为设问，句中并没有作者自己的回答；C 项误判为一般疑问句，作者并非真的在征求意见；D 项把意思弄反了。","options":["设问，自问自答，强调时间宝贵","反问，意思是「我们不能浪费时间」","一般疑问句，需要对方回答「能」或「不能」","反问，意思是「我们能浪费时间」"],"difficulty":2,"tags":["修辞","反问"]},{"id":"v-xiuci-fanwen-q2","type":"choice","stem":"「难道我们不应该珍惜今天的幸福生活吗？」改为陈述句，正确的一项是（ ）","answer":"B","explain":"改法分两步：先去掉疑问语气词「难道」和句末问号，把问号改成句号；再做「否定之否定」的转换，原句中的否定词「不」要删去，意思才不变，故应改为「我们应该珍惜今天的幸福生活」。A 项漏掉了删去「不」这一步，把意思弄反了；C 项改变了原意；D 项只是把问号改成了句号，句式和语气都还是反问，不是陈述句。","options":["我们不应该珍惜今天的幸福生活。","我们应该珍惜今天的幸福生活。","我们今天应该幸福地生活。","我们难道应该珍惜今天的幸福生活吗。"],"difficulty":2,"tags":["修辞","反问","句式转换"]},{"id":"v-xiuci-fanwen-q3","type":"fill","stem":"用疑问的形式表达确定的意思，答案就在问句之中、不需要回答，这种修辞手法叫（ ）。","answer":"反问|反诘","explain":"这是反问的定义，也叫反诘、激问。它与设问的区别是：反问问中有答、不需回答；设问自问自答、答案在问句之外。改写成陈述句时要注意「否定之否定」：原句有否定词的要删去，没有否定词的要加上。","difficulty":1,"tags":["修辞","反问","定义"]},{"id":"v-xiuci-fanwen-q4","type":"choice","stem":"下列关于反问与设问的区分，说法正确的一项是（ ）","answer":"A","explain":"反问与设问的根本区别在于答案的位置：反问问中有答，用疑问的形式表达确定的意思，不需回答；设问自问自答，答案在问句之外，A 项正确。B 项错在反问不需要读者回答；C 项混淆了「无疑而问」与「有疑而问」，二者都是无疑而问，并非真的不知答案；D 项错在反问兼表肯定与否定，如「难道这不是奇迹吗」表达的是强烈的肯定。","options":["反问的答案就在问句之中，不需要回答；设问的答案在问句之外，由作者自己回答","反问需要读者来回答，设问由作者自己回答","反问和设问都是「有疑而问」，确实需要别人提供答案","反问句中没有否定词，所以反问只能表达否定的意思"],"difficulty":3,"tags":["修辞","反问","易混辨析"]}]},{"id":"v-xiuci-bianxi","title":"易混修辞辨析","subtitle":"修辞手法 · yì hùn xiū cí biàn xī","grade":"all","tags":["修辞手法"],"blocks":[{"type":"meta","items":[{"k":"类别","v":"修辞手法"},{"k":"读音","v":"yì hùn xiū cí biàn xī"}]},{"type":"p","text":"对偶、反复、设问、反问这四种修辞，形式上或表现为「成双成串」，或表现为「带着问号」，在考试中极易混淆。辨析的总方法是「两步走」：第一步看形式特征——共有几句（两项还是三项以上）、字数是否相等、结构是否相同或相似、有没有原样重复的词语、有没有问号；第二步看表达目的——是为了形式对称，是为了强调情感，是为了引起注意，还是为了加强语气。形式与目的两头一对，修辞手法就能准确判定。"},{"type":"note","title":"易错提示","text":"五组易混点集中对比。一、对偶与排比：数项数。对偶恰好两项，字数相等、结构相同、词性相对；排比三项或三项以上，结构相似、语气一致，字数可以不相等。三项以上连排一定是排比，不可能是对偶。二、对偶与对比：看意图。对偶讲究形式对称，是「对称」之美；对比讲究内容对立，是「对立」之效，不要求字数相等、结构对称。两项既对称又对立的是对偶兼对比，只对立而不对称的只是对比。三、反复与排比：看重复的是什么。反复是同一个词语或句子原样重复，重复的是字面，两项即可；排比是结构相似、内容相关的三项以上连用，重复的是结构，字面一般不同。四、设问与反问：看有没有答案。设问是自问自答，答案在问句之外；反问是问中有答，答案就在问句之中，不需回答。五、反复与啰嗦：看有没有表达需要。反复是为强调情感、增强语势而有意重复；啰嗦是无意义地重复同一个意思，删去后表达更好。另外要记住两点共同特征：设问与反问都使用问句形式，都是「无疑而问」，都不是真的提问；对偶与反复都与问号无关，判断时不必考虑疑问语气。"},{"type":"quote","text":"对偶：无边落木萧萧下，不尽长江滚滚来。（杜甫《登高》）\n排比：他们的品质是那样的纯洁和高尚，他们的意志是那样的坚韧和刚强，他们的气质是那样的淳朴和谦逊，他们的胸怀是那样的美丽和宽广！（魏巍《谁是最可爱的人》）\n反复：沉默呵，沉默呵！不在沉默中爆发，就在沉默中灭亡。（鲁迅《记念刘和珍君》）\n设问：谁是我们最可爱的人呢？我们的战士，我感到他们是最可爱的人。（魏巍《谁是最可爱的人》）\n反问：难道我们能浪费时间吗？（现代文例句）","source":"例句"},{"type":"table","title":"易混辨析","head":["易混词","释义"],"rows":[["对比","把两个相反或相对的事物（或同一事物的两个方面）并举比较，重在内容对立，不要求字数相等、结构对称。与对偶的区别是「重内容」与「重形式」。"],["排比","三个或三个以上结构相似、语气一致的短语或句子连用，重在铺排气势，字数可以不完全相等。与对偶的区别在项数，与反复的区别在重复的是结构而非字面。"],["反问","用疑问的形式表达确定的意思，答案在问句之中、不需回答。与设问的区别是：反问问中有答，设问自问自答、答案在问句之外。"]]},{"type":"h","text":"方法"},{"type":"list","title":"怎么学","items":["把形近字、音近字分组对比，用「偏旁表义」帮助记忆。","词语（成语）先看感情色彩与使用对象，再代入语境验证。","近义词用「换词法」比较：换进去句意是否变化、搭配是否成立。","修辞题先说手法，再说「写出了什么 + 表达了什么」。","错题按「字音 / 字形 / 成语 / 辨析 / 修辞」归档，每周回看一次。"]},{"type":"list","title":"考查点","items":["字音字形","成语运用","近义辨析","修辞与表达效果","病句修改"]}],"questions":[{"id":"v-xiuci-bianxi-q1","type":"choice","stem":"「他们的品质是那样的纯洁和高尚，他们的意志是那样的坚韧和刚强，他们的气质是那样的淳朴和谦逊，他们的胸怀是那样的美丽和宽广！」这句运用的修辞手法是（ ）","answer":"B","explain":"四个结构相同、语气一致的句子连用，是典型的排比。它不止两项，所以不是对偶，对偶恰好两项且字数相等；句中各项并列铺排、内容并不相反相对，不是对比；句中没有提问，也不是设问。","options":["对偶","排比","对比","设问"],"difficulty":2,"tags":["修辞","排比","易混辨析"]},{"id":"v-xiuci-bianxi-q2","type":"choice","stem":"「无边落木萧萧下，不尽长江滚滚来」是对偶，下列对其表达效果的分析最恰当的一项是（ ）","answer":"A","explain":"这两句是严整的对偶，A 项从字数、结构、词性相对的角度说明了对偶形式整齐、节奏鲜明、富有气势的效果，分析最恰当。B 项说的是设问，句中并无问答；C 项说的是反复，「萧萧」「滚滚」是叠词，不是同一词语的重复；D 项把对偶误说成对比，落木与长江是相衬的秋景，并不构成内容上的对立。","options":["两句字数相等、结构相同，「无边」对「不尽」、「落木」对「长江」，形式整齐、节奏鲜明，把秋景的雄浑壮阔写得气势磅礴","以自问自答的方式强调秋天的萧瑟，引起读者注意","用同一个词语反复出现来强化悲凉之情","把落木与长江两个相反的事物并举，突出二者的对立"],"difficulty":3,"tags":["修辞","对偶","表达效果"]},{"id":"v-xiuci-bianxi-q3","type":"fill","stem":"把两个相反或相对的事物（或同一事物的两个方面）并举比较，重在内容对立，不要求字数相等、结构对称，这种手法叫（ ）。","answer":"对比|对照","explain":"这是对比的定义。它与对偶的区别是：对偶是形式上的对称，要求两项字数相等、结构相同、词性相对；对比是内容上的对立，不拘字数与结构。两项既对称又对立时，可以说既是对偶又是对比。","difficulty":2,"tags":["修辞","对比","定义"]},{"id":"v-xiuci-bianxi-q4","type":"choice","stem":"下列对几种易混修辞的区分，正确的一项是（ ）","answer":"A","explain":"对偶与排比的分界就在项数与字数要求上，A 项正确。B 项错在反复两项即可（如「盼望着，盼望着」），且排比各项字面一般不同；C 项错在只有反问是只问不答、答案在问中，设问是自问自答、答案在问句之外；D 项错在对比只要求内容对立，字数相等、结构对称是形式上的要求，是「对偶」的特点，不是对比的必备条件。","options":["对偶恰好两项且字数相等、结构相同；排比须三项以上，结构相似而字数可以不等","反复与排比一样，都必须三项以上，而且各项字面完全相同","设问和反问都只问不答，答案都在问句之中","对比要求字数相等、结构对称，否则不能构成对比"],"difficulty":3,"tags":["修辞","易混辨析","综合"]}]}];
